FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "funkce"."id_funkce" > 1910 AND "typ_funkce"."id_typ_org" > 22 AND "typ_funkce"."typ_funkce_obecny" IS NULL AND "typ_organu"."id_typ_org" != 88 GROUP BY "typ_funkce"."id_typ_org", "funkce"."id_funkce", "typ_organu"."id_typ_org", "typ_organu"."nazev_typ_org_cz" ORDER BY "typ_organu"."id_typ_org" DESC, MIN("typ_funkce"."id_typ_funkce") ASC;

SELECT "bod_stav"."popis", "schuze"."id_organ", "bod_schuze"."id_bod_stav", COUNT("schuze"."schuze")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "bod_schuze"."id_typ" = '5' AND "schuze"."id_schuze" >= 399 AND "bod_stav"."popis" = 'jiz projednan' GROUP BY "bod_stav"."popis", "schuze"."id_organ", "bod_schuze"."id_bod_stav" HAVING COUNT("schuze"."schuze") > 2 LIMIT 134;

SELECT "bod_schuze"."uplny_naz", "bod_schuze"."poznamka", "schuze"."od_schuze", "bod_schuze"."zkratka", "bod_schuze"."id_typ", COUNT("bod_schuze"."id_schuze"), SUM("bod_schuze"."id_bod_stav"), MIN("bod_schuze"."id_bod")
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."id_organ" < 170 AND "schuze"."aktualizace" != '2011-06-21 21:21' AND "bod_schuze"."id_tisk" LIKE '%39546%' AND "schuze"."do_schuze" = '2000-07-14 14' GROUP BY "bod_schuze"."uplny_naz", "bod_schuze"."poznamka", "schuze"."od_schuze", "bod_schuze"."zkratka", "bod_schuze"."id_typ" ORDER BY SUM("bod_schuze"."id_bod_stav") DESC, COUNT("bod_schuze"."id_schuze") ASC;

