FROM "osoby" LEFT JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "poslanec"."psp_telefon" IS NOT NULL AND "osoby"."umrti" = '16.10.1934' GROUP BY "poslanec"."email", "poslanec"."id_poslanec" ORDER BY "poslanec"."id_poslanec" ASC, COUNT("osoby"."id_osoba") ASC LIMIT 859;

