FROM "bod_stav" JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" WHERE "bod_schuze"."druh_bodu" IS NULL AND "bod_stav"."popis" != 'přerušen' AND "bod_schuze"."uplny_naz" LIKE '%Návrh poslanců Anny Putnové, Karla Schwarzenberga, Vlasty Bohdalové, Heleny Langšádlové, Františka Váchy, Augustina Karla Andrleho Sylora, Jany Fischerové, Bohuslava Svobody, Zbyňka Stanjury, Věry Kovářové, Jana Zahradníka, Markéty Wernerové a Jaroslava Lobkowicze na vydání zákona, kterým se mění zákon č. 561/2004 Sb., o předškolním, základním, středním, vyšším odborném a jiném vzdělávání (školský zákon), ve znění pozdějších předpisů a zákon č. 563/2004 Sb., o pedagogických pracovnících a o změně některých zákonů (zákon o pedagogických pracovnících), ve znění pozdějších předpisů%' AND "bod_stav"."id_bod_stav" = 3 AND "bod_schuze"."poznamka" != 'nejdříve od 1.7.' GROUP BY "bod_stav"."popis", "bod_schuze"."rj" ORDER BY "bod_schuze"."rj" ASC, AVG("bod_schuze"."id_schuze") DESC;

