SELECT "typ_organu"."id_typ_org", "organy"."nazev_organu_en", MIN("organy"."id_organ"), SUM("organy"."cl_organ_base")
FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" WHERE "typ_organu"."priorita" > 15 AND "typ_organu"."typ_id_typ_org" = '20' AND "typ_organu"."nazev_typ_org_cz" = 'Prezídium' AND "organy"."do_organ" IS NOT NULL AND "typ_organu"."nazev_typ_org_cz" = 'Federální shromáždění Československé socialistické republiky' GROUP BY "typ_organu"."id_typ_org", "organy"."nazev_organu_en" HAVING SUM("organy"."cl_organ_base") > 91 LIMIT 479;

SELECT "typ_organu"."id_typ_org", "typ_organu"."typ_id_typ_org", MIN("typ_organu"."id_typ_org"), COUNT("organy"."id_organ")
FROM "organy" JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "organy"."id_organ" != 302 GROUP BY "typ_organu"."id_typ_org", "typ_organu"."typ_id_typ_org" ORDER BY MIN("typ_organu"."id_typ_org") DESC, COUNT("organy"."id_organ") ASC;

SELECT "typ_organu"."priorita", "typ_organu"."typ_org_obecny", "hl_hlasovani"."nehlasoval", "hl_zposlanec"."id_hlasovani", SUM("typ_organu"."priorita"), MIN("hl_zposlanec"."id_osoba"), COUNT("hl_hlasovani"."kvorum")
FROM "hl_zposlanec" JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "hl_zposlanec"."id_hlasovani" != 59522 AND "hl_hlasovani"."pro" >= 122 AND "hl_zposlanec"."mode" = 1 AND "organy"."od_organ" != '10.02.1999' AND "typ_organu"."id_typ_org" < 42 GROUP BY "typ_organu"."priorita", "typ_organu"."typ_org_obecny", "hl_hlasovani"."nehlasoval", "hl_zposlanec"."id_hlasovani" HAVING SUM("typ_organu"."priorita") > 100 ORDER BY "hl_zposlanec"."id_hlasovani" DESC, MIN("hl_zposlanec"."id_osoba") DESC;

SELECT "schuze_stav"."text_dt", "schuze"."id_organ", "bod_schuze"."bod", "bod_stav"."id_bod_stav", "bod_schuze"."id_bod", MAX("bod_stav"."id_bod_stav"), AVG("schuze"."id_organ")
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "bod_schuze"."uplny_naz" != 'Návrh poslanců Zdeňky Horníkové, Lenky Andrýsové, Václava Horáčka a dalších na vydání zákona, kterým se mění zákon č. 211/2000 Sb., o Státním fondu rozvoje bydlení a o změně zákona č. 171/1991 Sb., o působnosti orgánů České republiky ve věcech převodů majetku státu na jiné osoby a o Fondu národního majetku České republiky, ve znění pozdějších předpisů' AND "schuze"."do_schuze" != '2002-09-13 17' AND "bod_schuze"."druh_bodu" != '3' GROUP BY "schuze_stav"."text_dt", "schuze"."id_organ", "bod_schuze"."bod", "bod_stav"."id_bod_stav", "bod_schuze"."id_bod" HAVING MAX("bod_stav"."id_bod_stav") > 5 ORDER BY AVG("schuze"."id_organ") ASC, "bod_schuze"."bod" DESC;

SELECT "hl_hlasovani"."proti", "hl_hlasovani"."id_organ", MAX("hl_check"."turn")
FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_check"."turn" >= 198 AND "hl_hlasovani"."prihlaseno" < 196 GROUP BY "hl_hlasovani"."proti", "hl_hlasovani"."id_organ" LIMIT 63;

SELECT "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "hl_vazby"."typ", "hl_vazby"."turn", "zmatecne"."id_hlasovani", SUM("hl_vazby"."typ"), COUNT("hl_vazby"."typ"), SUM("hl_hlasovani"."proti")
FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "hl_vazby"."turn" > 361 AND "zmatecne"."id_hlasovani" >= 60406 AND "hl_hlasovani"."id_hlasovani" >= 58424 AND "zmatecne"."id_hlasovani" = 59273 GROUP BY "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "hl_vazby"."typ", "hl_vazby"."turn", "zmatecne"."id_hlasovani" HAVING SUM("hl_hlasovani"."proti") > 57 ORDER BY "hl_vazby"."typ" ASC, "zmatecne"."id_hlasovani" ASC LIMIT 786;

SELECT "typ_organu"."priorita", "typ_funkce"."id_typ_org", "typ_funkce"."id_typ_org", "typ_funkce"."typ_funkce_cz", MIN("typ_organu"."id_typ_org"), MIN("typ_organu"."priorita")
FROM "typ_organu" LEFT JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" WHERE "typ_funkce"."typ_funkce_cz" = '5. místopředseda' AND "typ_funkce"."priorita" > 717 AND "typ_organu"."id_typ_org" <= 47 AND "typ_funkce"."id_typ_org" = 17 AND "typ_funkce"."id_typ_funkce" != 128 GROUP BY "typ_organu"."priorita", "typ_funkce"."id_typ_org", "typ_funkce"."id_typ_org", "typ_funkce"."typ_funkce_cz" HAVING MIN("typ_organu"."id_typ_org") > 59 ORDER BY "typ_funkce"."id_typ_org" DESC, MIN("typ_organu"."id_typ_org") ASC;

SELECT "funkce"."id_funkce", "funkce"."id_organ", "funkce"."id_funkce", "hl_hlasovani"."bod", SUM("hl_hlasovani"."id_hlasovani")
FROM "schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" LEFT JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "organy"."id_organ" < 1032 OR "organy"."organ_id_organ" <= -6 GROUP BY "funkce"."id_funkce", "funkce"."id_organ", "funkce"."id_funkce", "hl_hlasovani"."bod" HAVING SUM("hl_hlasovani"."id_hlasovani") > 32 ORDER BY "funkce"."id_funkce" DESC, "hl_hlasovani"."bod" DESC LIMIT 38;

SELECT "hl_check"."id_hlasovani", "hl_hlasovani"."nehlasoval", "hl_check"."id_h3", "hl_check"."turn", "hl_hlasovani"."datum", MAX("hl_check"."turn"), MIN("hl_check"."turn")
FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_check"."mode" = 6 GROUP BY "hl_check"."id_hlasovani", "hl_hlasovani"."nehlasoval", "hl_check"."id_h3", "hl_check"."turn", "hl_hlasovani"."datum" HAVING MIN("hl_check"."turn") > 65 LIMIT 282;

SELECT "zarazeni"."do_f", "poslanec"."foto", COUNT("osoby"."id_osoba"), SUM("osoby"."id_osoba"), COUNT("zarazeni"."id_of")
FROM "hl_poslanec" JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" WHERE "hl_poslanec"."id_poslanec" <= 1471 AND "zarazeni"."od_o" LIKE '%1946-05-26 00%' AND "poslanec"."ulice" LIKE '%Pod Vršky 45%' GROUP BY "zarazeni"."do_f", "poslanec"."foto" HAVING SUM("osoby"."id_osoba") > 77 ORDER BY "poslanec"."foto" ASC, SUM("osoby"."id_osoba") ASC LIMIT 53;

