FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_check"."turn" < 41 AND "hl_check"."mode" >= 1 AND "hl_hlasovani"."zdrzel" > 27 AND "hl_hlasovani"."nazev_dlouhy" != 'Novela z. o ochraně zemědělského půdního fondu' AND "hl_hlasovani"."pro" > 131 GROUP BY "hl_check"."mode", "hl_check"."id_h2" ORDER BY "hl_check"."id_h2" DESC, "hl_check"."mode" ASC;

SELECT "poslanec"."telefon", "osoby"."pred", "osoby"."narozeni", "hl_poslanec"."vysledek", "osoby"."prijmeni", COUNT("hl_poslanec"."id_hlasovani"), MAX("poslanec"."id_obdobi")
FROM "osoby" JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" WHERE "zarazeni"."od_o" LIKE '%2014-02-13 00%' AND "zarazeni"."do_o" IS NOT NULL GROUP BY "poslanec"."telefon", "osoby"."pred", "osoby"."narozeni", "hl_poslanec"."vysledek", "osoby"."prijmeni" ORDER BY MAX("poslanec"."id_obdobi") DESC, "osoby"."prijmeni" DESC;

