FROM "schuze" LEFT JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "bod_schuze"."uplny_naz" = 'Návrh poslanců Milana Urbana, Cyrila Zapletala, Břetislava Petra, Vlastimila Aubrechta, Gabriely Kalábkové a Petra Červenky na vydání zákona, kterým se mění zákon č. 406/2000 Sb., o hospodaření energií, ve znění pozdějších předpisů, a některé další zákony' GROUP BY "schuze"."do_schuze", "schuze"."id_organ", "schuze"."od_schuze", "bod_schuze"."id_tisk" LIMIT 320;

SELECT "schuze"."aktualizace", "bod_schuze"."poznamka", "schuze"."schuze", "bod_schuze"."druh_bodu", MIN("bod_schuze"."id_bod_stav"), MAX("organy"."id_typ_organu")
