FROM "poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" WHERE "poslanec"."telefon" IS NULL GROUP BY "poslanec"."telefon", "poslanec"."web", "osoby"."id_osoba", "poslanec"."id_kraj" HAVING MIN("poslanec"."id_obdobi") > 30 ORDER BY "poslanec"."web" ASC, "osoby"."id_osoba" ASC;

