SELECT "osoby"."id_osoba", "osoby"."umrti", "zarazeni"."cl_funkce", "zarazeni"."cl_funkce", "hl_zposlanec"."id_hlasovani", COUNT("osoby"."id_osoba"), SUM("hl_zposlanec"."id_osoba"), MIN("zarazeni"."id_osoba")
FROM "osoby" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" WHERE "zarazeni"."od_f" != '18.02.2014' AND "osoby"."pohlavi" = 'Z' AND "zarazeni"."od_f" IS NOT NULL GROUP BY "osoby"."id_osoba", "osoby"."umrti", "zarazeni"."cl_funkce", "zarazeni"."cl_funkce", "hl_zposlanec"."id_hlasovani" HAVING COUNT("osoby"."id_osoba") > 29;

SELECT "omluvy"."do", "typ_organu"."priorita", "organy"."cl_organ_base", "omluvy"."do", "organy"."do_organ", MAX("typ_funkce"."id_typ_org"), AVG("organy"."id_organ")
FROM "typ_organu" JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" LEFT JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "omluvy"."den" LIKE '%08.12.2010%' AND "organy"."zkratka" != 'PS' GROUP BY "omluvy"."do", "typ_organu"."priorita", "organy"."cl_organ_base", "omluvy"."do", "organy"."do_organ" LIMIT 140;

