FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" LEFT JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "schuze"."schuze" <= 34 AND "organy"."nazev_organu_cz" LIKE '%Podvýbor pro přípravu novely zákona o jednacím řádu Poslanecké sněmovny%' AND "schuze"."id_schuze" > 93 AND "typ_organu"."priorita" != 35 GROUP BY "typ_organu"."typ_id_typ_org", "schuze"."aktualizace", "typ_organu"."nazev_typ_org_en", "schuze"."do_schuze", "schuze"."id_organ" ORDER BY AVG("schuze"."schuze") ASC, "typ_organu"."typ_id_typ_org" DESC;

SELECT "poslanec"."id_kraj", "omluvy"."id_organ", "omluvy"."od", MIN("poslanec"."id_poslanec"), MAX("poslanec"."id_kandidatka"), SUM("poslanec"."id_kandidatka")
