FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" WHERE "bod_schuze"."id_bod" < 17665 AND "bod_stav"."popis" != 'přerušen' AND "bod_schuze"."id_schuze" > 344 AND "bod_stav"."id_bod_stav" <= 1 AND "bod_stav"."popis" = 'neprojednatelný' GROUP BY "bod_stav"."id_bod_stav", "bod_schuze"."rj", "bod_stav"."popis" HAVING MAX("bod_schuze"."id_bod_stav") > 69 ORDER BY MAX("bod_schuze"."id_bod_stav") ASC, "bod_stav"."popis" ASC;

SELECT "bod_schuze"."uplny_naz", "bod_stav"."id_bod_stav", MIN("bod_stav"."id_bod_stav"), SUM("bod_stav"."id_bod_stav"), AVG("bod_schuze"."id_bod_stav")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "bod_schuze"."id_sd" != '7823' AND "schuze"."id_schuze" >= 105 AND "schuze"."do_schuze" = '2003-06-10 17' GROUP BY "bod_schuze"."uplny_naz", "bod_stav"."id_bod_stav";

SELECT "schuze"."schuze", "organy"."priorita", "organy"."id_organ", "bod_schuze"."pozn2", AVG("bod_schuze"."bod"), SUM("bod_stav"."id_bod_stav")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "organy"."priorita" IS NOT NULL AND "bod_stav"."popis" != 'přerušen' AND "organy"."organ_id_organ" < -9 GROUP BY "schuze"."schuze", "organy"."priorita", "organy"."id_organ", "bod_schuze"."pozn2" ORDER BY SUM("bod_stav"."id_bod_stav") DESC, "organy"."id_organ" ASC LIMIT 228;

SELECT "typ_funkce"."id_typ_org", "funkce"."priorita", "funkce"."priorita", "funkce"."id_organ", MIN("typ_funkce"."priorita"), COUNT("funkce"."id_funkce"), AVG("funkce"."id_typ_funkce")
FROM "typ_funkce" LEFT JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "funkce"."nazev_funkce_cz" != 'Místopředseda' AND "funkce"."nazev_funkce_cz" LIKE '%Předseda podvýboru PZ%' AND "typ_funkce"."typ_funkce_en" = 'Internal Auditor' GROUP BY "typ_funkce"."id_typ_org", "funkce"."priorita", "funkce"."priorita", "funkce"."id_organ" ORDER BY AVG("funkce"."id_typ_funkce") ASC, "typ_funkce"."id_typ_org" DESC;

SELECT "schuze"."id_schuze", "bod_schuze"."id_typ", "schuze"."od_schuze", "schuze"."od_schuze", "schuze"."schuze", AVG("schuze"."id_schuze")
FROM "schuze" LEFT JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "schuze"."id_schuze" > 246 AND "bod_schuze"."id_schuze" < 261 AND "bod_schuze"."zkratka" IS NULL AND "schuze"."id_organ" >= 169 GROUP BY "schuze"."id_schuze", "bod_schuze"."id_typ", "schuze"."od_schuze", "schuze"."od_schuze", "schuze"."schuze" ORDER BY "schuze"."schuze" ASC, "bod_schuze"."id_typ" DESC LIMIT 982;

SELECT "omluvy"."id_poslanec", "poslanec"."ulice", SUM("omluvy"."id_organ"), COUNT("poslanec"."id_obdobi"), MAX("omluvy"."id_organ")
FROM "omluvy" LEFT JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."ulice" != '\' OR "omluvy"."den" LIKE '%10.12.2010%' OR "poslanec"."id_kandidatka" != 107 OR "poslanec"."email" LIKE '%\%' GROUP BY "omluvy"."id_poslanec", "poslanec"."ulice" ORDER BY MAX("omluvy"."id_organ") ASC, "omluvy"."id_poslanec" ASC;

SELECT "bod_stav"."id_bod_stav", "bod_stav"."id_bod_stav", "bod_stav"."id_bod_stav", "bod_schuze"."bod", "bod_schuze"."rj", COUNT("bod_stav"."id_bod_stav"), AVG("organy"."id_organ"), MAX("bod_schuze"."id_bod")
