SELECT "hl_poslanec"."id_hlasovani", "poslanec"."fax", "poslanec"."obec", "poslanec"."fax", MIN("poslanec"."id_poslanec")
FROM "pkgps" LEFT JOIN "poslanec" ON "pkgps"."id_poslanec" = "poslanec"."id_poslanec" LEFT JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" WHERE "hl_poslanec"."id_hlasovani" > 59830 OR "poslanec"."id_obdobi" = 168 OR "poslanec"."id_poslanec" < 1382 OR "hl_poslanec"."id_hlasovani" > 59558 GROUP BY "hl_poslanec"."id_hlasovani", "poslanec"."fax", "poslanec"."obec", "poslanec"."fax" ORDER BY "poslanec"."obec" ASC, "poslanec"."fax" ASC;

