FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "hl_vazby"."typ" > -3 AND "hl_hlasovani"."id_hlasovani" > 60264 AND "hl_hlasovani"."bod" < 64 AND "hl_vazby"."typ" > 5 GROUP BY "organy"."do_organ", "organy"."nazev_organu_cz" ORDER BY "organy"."nazev_organu_cz" DESC, "organy"."do_organ" DESC LIMIT 34;

