FROM "bod_stav" JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" WHERE "schuze"."do_schuze" LIKE '%2012-03-21 15%' AND "bod_stav"."id_bod_stav" < 3 AND "schuze_stav"."text_dt" != '10 minut po ukončení 34. schůze' AND "schuze_stav"."text_st" != 'žádost vlády o vyslovení důvěry' AND "schuze_stav"."id_schuze" != 399 GROUP BY "bod_stav"."id_bod_stav", "bod_stav"."popis", "schuze_stav"."tm_line", "bod_schuze"."id_schuze", "bod_stav"."id_bod_stav" ORDER BY "bod_stav"."id_bod_stav" DESC, "bod_schuze"."id_schuze" ASC;

SELECT "hl_zposlanec"."id_hlasovani", "zarazeni"."od_o", "zarazeni"."cl_funkce", "hl_zposlanec"."id_hlasovani", "osoby"."zmena", COUNT("osoby"."id_osoba")
FROM "osoby" LEFT JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" WHERE "zarazeni"."do_o" != '2013-08-28 00' AND "osoby"."pohlavi" != 'M' GROUP BY "hl_zposlanec"."id_hlasovani", "zarazeni"."od_o", "zarazeni"."cl_funkce", "hl_zposlanec"."id_hlasovani", "osoby"."zmena" HAVING COUNT("osoby"."id_osoba") > 10 LIMIT 562;

SELECT "organy"."nazev_organu_en", "funkce"."id_typ_funkce", SUM("typ_organu"."priorita")
FROM "organy" JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" LEFT JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "organy"."id_organ" < 164 AND "typ_organu"."typ_id_typ_org" != '20' AND "typ_organu"."id_typ_org" = 22 AND "typ_organu"."nazev_typ_org_en" = 'Czech republic' GROUP BY "organy"."nazev_organu_en", "funkce"."id_typ_funkce" ORDER BY "organy"."nazev_organu_en" ASC, "funkce"."id_typ_funkce" ASC LIMIT 715;

SELECT "schuze"."aktualizace", "bod_schuze"."id_typ", "schuze"."id_organ", MAX("bod_schuze"."id_schuze"), SUM("schuze"."id_schuze"), MIN("bod_schuze"."bod")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "bod_schuze"."uplny_naz" LIKE '%Informace o vojenských cvičeních jednotek a štábů Armády České republiky se zahraničními partnery na území České republiky i mimo ně za období leden - červen 2010%' GROUP BY "schuze"."aktualizace", "bod_schuze"."id_typ", "schuze"."id_organ" ORDER BY "schuze"."aktualizace" DESC, MIN("bod_schuze"."bod") ASC LIMIT 312;

