FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."id_organ" >= 170 AND "schuze_stav"."id_schuze" = 378 AND "schuze_stav"."text_st" IS NOT NULL AND "schuze_stav"."text_st" != 'volba veřejného ochránce práv' AND "schuze_stav"."text_dt" IS NULL GROUP BY "schuze_stav"."tm_line", "schuze_stav"."typ" HAVING MAX("schuze"."schuze") > 35 ORDER BY "schuze_stav"."typ" ASC, COUNT("schuze"."id_organ") DESC;

