FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "bod_schuze"."id_bod_stav" > 11 GROUP BY "schuze"."od_schuze", "schuze"."aktualizace", "bod_schuze"."id_typ", "organy"."nazev_organu_en", "bod_schuze"."id_bod_stav" HAVING COUNT("schuze"."id_schuze") > 52 ORDER BY "schuze"."od_schuze" DESC, "schuze"."aktualizace" DESC;

