FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" LEFT JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "osoby"."zmena" != '20.04.2000' AND "zarazeni"."od_f" IS NOT NULL GROUP BY "zarazeni"."od_o", "poslanec"."obec", "zarazeni"."cl_funkce", "zarazeni"."do_o", "zarazeni"."od_f" ORDER BY "zarazeni"."od_f" ASC, "poslanec"."obec" ASC;

SELECT "hl_hlasovani"."datum", "hl_hlasovani"."id_organ", "hl_zposlanec"."id_osoba", "hl_hlasovani"."zdrzel", "hl_hlasovani"."nazev_dlouhy", COUNT("organy"."id_organ")
