SELECT "hl_hlasovani"."pro", "hl_vazby"."id_hlasovani", "organy"."id_organ", "hl_hlasovani"."cas", "hl_hlasovani"."nazev_kratky", MAX("hl_vazby"."typ"), AVG("hl_hlasovani"."schuze")
FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "hl_vazby"."typ" >= 0 GROUP BY "hl_hlasovani"."pro", "hl_vazby"."id_hlasovani", "organy"."id_organ", "hl_hlasovani"."cas", "hl_hlasovani"."nazev_kratky" HAVING MAX("hl_vazby"."typ") > 75 ORDER BY AVG("hl_hlasovani"."schuze") DESC, "hl_hlasovani"."pro" ASC;

