FROM "bod_stav" JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."aktualizace" != '2003-01-17 10:39' AND "bod_schuze"."id_bod_stav" = 7 AND "bod_stav"."id_bod_stav" >= 5 AND "schuze"."do_schuze" LIKE '%2007-09-27 19%' GROUP BY "bod_stav"."popis", "bod_schuze"."pozvanka", "schuze"."aktualizace" ORDER BY COUNT("bod_stav"."id_bod_stav") DESC, "schuze"."aktualizace" DESC LIMIT 663;

SELECT "poslanec"."psp_telefon", "pkgps"."adresa", "hl_poslanec"."id_hlasovani", "hl_poslanec"."id_poslanec", MAX("hl_poslanec"."id_hlasovani"), AVG("hl_poslanec"."id_poslanec")
FROM "hl_poslanec" LEFT JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" JOIN "omluvy" ON "poslanec"."id_poslanec" = "omluvy"."id_poslanec" WHERE "poslanec"."web" = 'http://www.igor-nykl.cz/' AND "pkgps"."delka" > 14.626919556582948 GROUP BY "poslanec"."psp_telefon", "pkgps"."adresa", "hl_poslanec"."id_hlasovani", "hl_poslanec"."id_poslanec" ORDER BY "hl_poslanec"."id_hlasovani" DESC, "poslanec"."psp_telefon" DESC LIMIT 95;

