FROM "poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "pkgps"."sirka" <= 48.87549900621943 GROUP BY "osoby"."umrti", "poslanec"."psp_telefon" HAVING SUM("poslanec"."id_kraj") > 76 LIMIT 522;

