FROM "osoby" JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" LEFT JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "osoby"."id_osoba" <= 4165 AND "osoby"."prijmeni" LIKE '%Augustin%' AND "hl_hlasovani"."nazev_dlouhy" LIKE '%Novela z. o ochraně zemědělského půdního fondu%' AND "hl_hlasovani"."cislo" != 148 AND "hl_hlasovani"."cislo" < 252 GROUP BY "hl_zposlanec"."mode", "osoby"."umrti", "hl_hlasovani"."id_hlasovani" HAVING COUNT("hl_zposlanec"."mode") > 82 ORDER BY "hl_hlasovani"."id_hlasovani" ASC, COUNT("hl_zposlanec"."mode") DESC;

SELECT "organy"."organ_id_organ", "hl_vazby"."turn", "hl_vazby"."turn", "organy"."id_organ", "organy"."nazev_organu_cz", COUNT("hl_hlasovani"."zdrzel"), MIN("organy"."id_organ")
FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "zmatecne"."id_hlasovani" < 59248 OR "zmatecne"."id_hlasovani" != 61220 OR "hl_hlasovani"."nehlasoval" != 0 GROUP BY "organy"."organ_id_organ", "hl_vazby"."turn", "hl_vazby"."turn", "organy"."id_organ", "organy"."nazev_organu_cz" ORDER BY MIN("organy"."id_organ") ASC, COUNT("hl_hlasovani"."zdrzel") ASC;

SELECT "bod_schuze"."uplny_kon", "bod_schuze"."id_tisk", COUNT("bod_schuze"."bod"), AVG("bod_schuze"."id_schuze")
FROM "bod_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "bod_stav"."popis" != 'právě projednávaný' AND "bod_schuze"."uplny_naz" = 'Návrh poslanců Romana Sklenáka, Jeronýma Tejce a dalších na vydání zákona, kterým se mění zákon č. 218/2002 Sb., o službě státních zaměstnanců ve správních úřadech a o odměňování těchto zaměstnanců a ostatních zaměstnanců ve správních úřadech (služební zákon)' AND "bod_stav"."id_bod_stav" >= 4 GROUP BY "bod_schuze"."uplny_kon", "bod_schuze"."id_tisk" LIMIT 224;

SELECT "bod_schuze"."id_tisk", "schuze"."aktualizace", "schuze"."od_schuze", SUM("bod_schuze"."id_bod_stav"), COUNT("schuze_stav"."id_schuze"), SUM("bod_schuze"."bod")
