FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" WHERE "typ_organu"."id_typ_org" = 72 AND "organy"."cl_organ_base" = -4 GROUP BY "typ_organu"."typ_id_typ_org", "organy"."od_organ", "organy"."zkratka", "typ_organu"."typ_org_obecny", "typ_organu"."typ_org_obecny" HAVING MIN("typ_organu"."priorita") > 85 ORDER BY "typ_organu"."typ_org_obecny" ASC, "typ_organu"."typ_org_obecny" ASC LIMIT 193;

