SELECT "poslanec"."psc", "zarazeni"."id_osoba", "poslanec"."psc", "poslanec"."obec", "zarazeni"."do_f", AVG("poslanec"."id_kandidatka"), AVG("zarazeni"."id_of"), AVG("zarazeni"."id_osoba")
