SELECT "zmatecne"."id_hlasovani", "hl_hlasovani"."kvorum", "hl_check"."id_h2", MAX("zmatecne"."id_hlasovani"), AVG("zmatecne"."id_hlasovani")
FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "hl_hlasovani"."cas" != 'default' OR "hl_hlasovani"."kvorum" = 119 GROUP BY "zmatecne"."id_hlasovani", "hl_hlasovani"."kvorum", "hl_check"."id_h2" ORDER BY MAX("zmatecne"."id_hlasovani") DESC, "hl_check"."id_h2" ASC;

SELECT "poslanec"."id_kandidatka", "organy"."od_organ", "organy"."zkratka", AVG("hl_hlasovani"."id_hlasovani"), COUNT("hl_hlasovani"."id_hlasovani"), AVG("hl_hlasovani"."pro")
FROM "organy" LEFT JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "omluvy"."od" = '16:00' AND "organy"."do_organ" IS NOT NULL AND "omluvy"."id_poslanec" != 959 AND "organy"."organ_id_organ" IS NOT NULL GROUP BY "poslanec"."id_kandidatka", "organy"."od_organ", "organy"."zkratka";

SELECT "hl_hlasovani"."kvorum", "zmatecne"."id_hlasovani", "hl_hlasovani"."zdrzel", "zmatecne"."id_hlasovani", SUM("zmatecne"."id_hlasovani"), AVG("hl_hlasovani"."schuze")
FROM "hl_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" <= 59005 GROUP BY "hl_hlasovani"."kvorum", "zmatecne"."id_hlasovani", "hl_hlasovani"."zdrzel", "zmatecne"."id_hlasovani" HAVING AVG("hl_hlasovani"."schuze") > 90;

SELECT "typ_funkce"."typ_funkce_cz", "typ_funkce"."typ_funkce_en", "funkce"."nazev_funkce_cz", "funkce"."id_organ", "funkce"."id_organ", MIN("typ_funkce"."typ_funkce_obecny")
FROM "funkce" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "typ_funkce"."typ_funkce_obecny" IS NULL AND "funkce"."id_typ_funkce" > 8 AND "typ_funkce"."id_typ_funkce" >= 122 AND "funkce"."id_funkce" > 403 AND "typ_funkce"."typ_funkce_obecny" IS NOT NULL GROUP BY "typ_funkce"."typ_funkce_cz", "typ_funkce"."typ_funkce_en", "funkce"."nazev_funkce_cz", "funkce"."id_organ", "funkce"."id_organ" HAVING MIN("typ_funkce"."typ_funkce_obecny") > 86 ORDER BY "funkce"."nazev_funkce_cz" ASC, "typ_funkce"."typ_funkce_cz" DESC LIMIT 368;

SELECT "organy"."od_organ", "organy"."priorita", "funkce"."nazev_funkce_cz", "funkce"."priorita", MIN("funkce"."id_typ_funkce"), AVG("typ_organu"."id_typ_org"), MIN("typ_funkce"."priorita")
FROM "typ_funkce" LEFT JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" JOIN "typ_organu" ON "typ_funkce"."id_typ_org" = "typ_organu"."id_typ_org" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "organy"."do_organ" IS NOT NULL AND "organy"."do_organ" IS NULL AND "typ_organu"."priorita" >= 2 AND "typ_funkce"."priorita" > 81 AND "typ_funkce"."priorita" >= 2 GROUP BY "organy"."od_organ", "organy"."priorita", "funkce"."nazev_funkce_cz", "funkce"."priorita";

SELECT "hl_hlasovani"."id_organ", "hl_check"."id_h3", "hl_check"."id_h3", COUNT("hl_hlasovani"."kvorum")
FROM "hl_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_hlasovani"."vysledek" != 'A' AND "hl_hlasovani"."schuze" != 30 AND "hl_check"."id_hlasovani" > 59817 AND "hl_hlasovani"."schuze" = 27 AND "hl_check"."turn" < 50 GROUP BY "hl_hlasovani"."id_organ", "hl_check"."id_h3", "hl_check"."id_h3" ORDER BY "hl_check"."id_h3" ASC, "hl_hlasovani"."id_organ" ASC;

SELECT "schuze_stav"."id_schuze", "schuze_stav"."text_dt", "schuze"."od_schuze", "organy"."od_organ", COUNT("organy"."id_organ"), COUNT("schuze"."schuze")
FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "schuze"."schuze" = 38 AND "schuze"."do_schuze" != '2002-09-13 17' AND "organy"."priorita" != '140' AND "schuze_stav"."stav" != 7 AND "schuze"."id_organ" > 171 GROUP BY "schuze_stav"."id_schuze", "schuze_stav"."text_dt", "schuze"."od_schuze", "organy"."od_organ" HAVING COUNT("schuze"."schuze") > 83 ORDER BY "schuze_stav"."text_dt" ASC, COUNT("organy"."id_organ") DESC LIMIT 715;

SELECT "typ_organu"."typ_org_obecny", "funkce"."id_funkce", MIN("funkce"."id_funkce"), SUM("organy"."id_typ_organu"), MAX("organy"."cl_organ_base")
FROM "organy" LEFT JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "organy"."nazev_organu_cz" = 'Stálá delegace Parlamentu do Parlamentního shromáždění Rady Evropy' AND "funkce"."id_organ" < 804 AND "typ_organu"."typ_org_obecny" = '0' AND "typ_organu"."id_typ_org" = 21 AND "typ_organu"."nazev_typ_org_en" != 'Working Group' GROUP BY "typ_organu"."typ_org_obecny", "funkce"."id_funkce" ORDER BY MIN("funkce"."id_funkce") ASC, "funkce"."id_funkce" ASC LIMIT 577;

SELECT "typ_funkce"."id_typ_funkce", "typ_funkce"."priorita", MIN("organy"."id_typ_organu")
FROM "funkce" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "organy"."cl_organ_base" > -5 GROUP BY "typ_funkce"."id_typ_funkce", "typ_funkce"."priorita" ORDER BY MIN("organy"."id_typ_organu") ASC, "typ_funkce"."priorita" ASC;

SELECT "schuze"."id_schuze", "funkce"."id_organ", MAX("funkce"."id_funkce")
FROM "funkce" JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "schuze"."aktualizace" = '2001-01-29 08:39' GROUP BY "schuze"."id_schuze", "funkce"."id_organ" ORDER BY "funkce"."id_organ" DESC, "schuze"."id_schuze" DESC LIMIT 76;

SELECT "schuze"."aktualizace", "schuze"."od_schuze", "organy"."id_typ_organu", MIN("organy"."id_typ_organu"), COUNT("schuze"."id_schuze"), AVG("organy"."cl_organ_base")
FROM "schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "schuze"."id_schuze" >= 67 OR "schuze"."id_organ" <= 170 OR "organy"."id_organ" > 238 OR "schuze"."aktualizace" != '2000-06-26 12:00' OR "schuze"."schuze" <= 13 GROUP BY "schuze"."aktualizace", "schuze"."od_schuze", "organy"."id_typ_organu" ORDER BY "organy"."id_typ_organu" DESC, "schuze"."od_schuze" DESC;

SELECT "organy"."priorita", "omluvy"."id_organ", "typ_funkce"."id_typ_funkce", "organy"."nazev_organu_en", "organy"."nazev_organu_cz", MIN("typ_organu"."priorita"), COUNT("organy"."id_typ_organu")
FROM "typ_organu" JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "omluvy"."den" = '01.04.2015' AND "typ_funkce"."id_typ_funkce" >= 42 AND "typ_funkce"."typ_funkce_en" != 'Chairperson' GROUP BY "organy"."priorita", "omluvy"."id_organ", "typ_funkce"."id_typ_funkce", "organy"."nazev_organu_en", "organy"."nazev_organu_cz" HAVING COUNT("organy"."id_typ_organu") > 21 ORDER BY "organy"."nazev_organu_en" DESC, "omluvy"."id_organ" ASC LIMIT 11;

SELECT "hl_vazby"."id_hlasovani", "hl_check"."id_h3", "hl_check"."id_h2", "hl_check"."mode", "hl_vazby"."id_hlasovani", MAX("hl_vazby"."turn")
FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" WHERE "hl_vazby"."typ" = 1 AND "hl_vazby"."id_hlasovani" >= 58612 AND "hl_vazby"."typ" != 0 AND "hl_hlasovani"."zdrzel" > 7 GROUP BY "hl_vazby"."id_hlasovani", "hl_check"."id_h3", "hl_check"."id_h2", "hl_check"."mode", "hl_vazby"."id_hlasovani" LIMIT 481;

