FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" WHERE "schuze_stav"."typ" IS NULL AND "bod_schuze"."bod" = 173 AND "bod_schuze"."uplny_naz" LIKE '%Vládní návrh zákona, kterým se mění zákon č. 549/1991 Sb., o soudních poplatcích, ve znění pozdějších předpisů, zákon č. 292/2013 Sb., o zvláštních řízeních soudních, ve znění zákona č. 87/2015 Sb., a zákon č. 91/2012 Sb., o mezinárodním právu soukromém%' GROUP BY "schuze"."aktualizace", "schuze"."od_schuze" LIMIT 922;

SELECT "typ_organu"."priorita", "typ_organu"."priorita", "typ_funkce"."priorita", "typ_funkce"."typ_funkce_en", "typ_organu"."nazev_typ_org_en", AVG("organy"."id_organ"), MAX("typ_funkce"."priorita")
FROM "typ_organu" JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" WHERE "typ_organu"."typ_org_obecny" = '7' AND "typ_funkce"."priorita" >= 1 AND "typ_organu"."nazev_typ_org_cz" != 'Prezídium' AND "typ_organu"."priorita" >= 13 AND "organy"."zkratka" LIKE '%PRPS%' GROUP BY "typ_organu"."priorita", "typ_organu"."priorita", "typ_funkce"."priorita", "typ_funkce"."typ_funkce_en", "typ_organu"."nazev_typ_org_en";

SELECT "zarazeni"."od_o", "osoby"."pohlavi", "zarazeni"."od_o", "zarazeni"."do_o", MIN("zarazeni"."id_osoba")
FROM "zarazeni" LEFT JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" WHERE "osoby"."prijmeni" = 'Petr' AND "osoby"."umrti" != '09.05.1963' AND "osoby"."prijmeni" LIKE '%Jaroslava%' GROUP BY "zarazeni"."od_o", "osoby"."pohlavi", "zarazeni"."od_o", "zarazeni"."do_o" HAVING MIN("zarazeni"."id_osoba") > 3 ORDER BY "zarazeni"."od_o" DESC, "zarazeni"."do_o" ASC LIMIT 126;

SELECT "organy"."priorita", "organy"."zkratka", COUNT("schuze"."schuze"), AVG("organy"."cl_organ_base"), MIN("organy"."id_typ_organu")
FROM "bod_stav" JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_stav"."popis" = 'přerušen' AND "bod_schuze"."id_sd" = '7426' AND "organy"."id_organ" >= 536 GROUP BY "organy"."priorita", "organy"."zkratka" ORDER BY MIN("organy"."id_typ_organu") ASC, "organy"."priorita" DESC LIMIT 231;

SELECT "hl_check"."mode", "zmatecne"."id_hlasovani", SUM("hl_check"."mode")
FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" > 59278 AND "hl_check"."turn" < 66 AND "hl_check"."mode" <= 1 AND "hl_vazby"."id_hlasovani" >= 61687 GROUP BY "hl_check"."mode", "zmatecne"."id_hlasovani" ORDER BY "zmatecne"."id_hlasovani" ASC, SUM("hl_check"."mode") ASC LIMIT 379;

SELECT "omluvy"."den", "omluvy"."id_organ", "hl_hlasovani"."cas", "poslanec"."psc", "poslanec"."psc", COUNT("omluvy"."id_poslanec"), MIN("omluvy"."id_poslanec")
FROM "omluvy" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" WHERE "omluvy"."id_organ" > 170 AND "omluvy"."id_poslanec" < 1061 GROUP BY "omluvy"."den", "omluvy"."id_organ", "hl_hlasovani"."cas", "poslanec"."psc", "poslanec"."psc" HAVING MIN("omluvy"."id_poslanec") > 72 ORDER BY COUNT("omluvy"."id_poslanec") DESC, "omluvy"."id_organ" DESC;

