FROM "pkgps" LEFT JOIN "poslanec" ON "pkgps"."id_poslanec" = "poslanec"."id_poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" WHERE "osoby"."zmena" = '01.01.1900' AND "osoby"."narozeni" = '01.01.1900' AND "pkgps"."id_poslanec" <= 1460 AND "osoby"."umrti" = '16.10.1934' AND "osoby"."prijmeni" != 'Antonín' GROUP BY "pkgps"."adresa", "pkgps"."id_poslanec", "pkgps"."id_poslanec", "poslanec"."id_poslanec", "osoby"."za" LIMIT 226;

SELECT "funkce"."id_typ_funkce", "funkce"."id_typ_funkce", "typ_funkce"."id_typ_funkce", "typ_funkce"."priorita", "organy"."do_organ", MIN("typ_funkce"."id_typ_funkce"), MAX("funkce"."id_organ")
FROM "typ_funkce" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "typ_funkce"."id_typ_funkce" > 134 AND "organy"."priorita" IS NOT NULL AND "funkce"."priorita" != -8 AND "typ_funkce"."typ_funkce_obecny" <= 1 AND "organy"."zkratka" LIKE '%PRU%' GROUP BY "funkce"."id_typ_funkce", "funkce"."id_typ_funkce", "typ_funkce"."id_typ_funkce", "typ_funkce"."priorita", "organy"."do_organ" HAVING MIN("typ_funkce"."id_typ_funkce") > 62 ORDER BY "organy"."do_organ" DESC, "funkce"."id_typ_funkce" ASC;

SELECT "hl_hlasovani"."pro", "hl_vazby"."id_hlasovani", MAX("hl_zposlanec"."id_osoba")
FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_vazby"."typ" = -3 OR "hl_vazby"."typ" >= 0 GROUP BY "hl_hlasovani"."pro", "hl_vazby"."id_hlasovani" ORDER BY "hl_vazby"."id_hlasovani" ASC, MAX("hl_zposlanec"."id_osoba") DESC LIMIT 235;

