FROM "bod_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."id_organ" < 168 AND "schuze"."aktualizace" LIKE '%2000-06-26 12:00%' AND "bod_schuze"."bod" < 56 GROUP BY "bod_stav"."id_bod_stav", "schuze"."aktualizace", "schuze"."do_schuze" HAVING COUNT("bod_schuze"."id_bod") > 11 ORDER BY SUM("bod_stav"."id_bod_stav") DESC, "schuze"."aktualizace" ASC;

