FROM "organy" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" LEFT JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "organy"."priorita" = '119' AND "zmatecne"."id_hlasovani" != 61649 GROUP BY "organy"."od_organ", "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "funkce"."nazev_funkce_cz" LIMIT 603;

