FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "hl_hlasovani"."vysledek" = 'A' GROUP BY "hl_check"."turn", "hl_hlasovani"."cas", "omluvy"."id_poslanec", "omluvy"."id_poslanec";

