SELECT "poslanec"."id_poslanec", "omluvy"."od", "omluvy"."den", "omluvy"."od", "omluvy"."do", MAX("poslanec"."id_osoba"), MIN("poslanec"."foto")
FROM "omluvy" JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."id_osoba" != 319 AND "omluvy"."id_poslanec" > 1123 AND "poslanec"."web" != 'http://www.janafischerova.cz' AND "poslanec"."id_poslanec" < 468 GROUP BY "poslanec"."id_poslanec", "omluvy"."od", "omluvy"."den", "omluvy"."od", "omluvy"."do" ORDER BY MAX("poslanec"."id_osoba") ASC, "omluvy"."od" DESC LIMIT 325;

SELECT "schuze"."do_schuze", "schuze"."id_schuze", AVG("schuze"."id_schuze")
