SELECT "typ_funkce"."typ_funkce_obecny", "typ_funkce"."typ_funkce_cz", "funkce"."priorita", "funkce"."priorita", SUM("omluvy"."id_poslanec"), COUNT("omluvy"."id_organ"), SUM("omluvy"."id_poslanec")
FROM "typ_funkce" LEFT JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" LEFT JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "funkce"."id_funkce" <= 1982 AND "funkce"."priorita" <= 2 GROUP BY "typ_funkce"."typ_funkce_obecny", "typ_funkce"."typ_funkce_cz", "funkce"."priorita", "funkce"."priorita" ORDER BY "funkce"."priorita" DESC, SUM("omluvy"."id_poslanec") ASC LIMIT 191;

