SELECT "schuze_stav"."id_schuze", "organy"."do_organ", "schuze"."od_schuze", "schuze"."aktualizace", SUM("bod_schuze"."id_bod"), MAX("organy"."id_organ"), MIN("schuze_stav"."id_schuze")
