SELECT "hl_hlasovani"."proti", "hl_hlasovani"."nehlasoval", "hl_hlasovani"."id_organ", "omluvy"."id_poslanec", AVG("omluvy"."id_organ"), COUNT("organy"."organ_id_organ")
