FROM "typ_funkce" LEFT JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" JOIN "typ_organu" ON "typ_funkce"."id_typ_org" = "typ_organu"."id_typ_org" WHERE "funkce"."id_organ" >= 807 AND "typ_funkce"."priorita" > 1 AND "typ_funkce"."id_typ_funkce" <= 111 GROUP BY "typ_funkce"."id_typ_org", "typ_organu"."priorita", "typ_funkce"."id_typ_funkce", "funkce"."id_funkce", "typ_funkce"."typ_funkce_cz";

