FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_stav"."popis" = 'jiz projednan' AND "organy"."nazev_organu_cz" != 'Výbor pro ekonomické a bezpečnostní otázky' AND "bod_stav"."popis" = 'odročen' AND "bod_schuze"."id_typ" != '54' AND "bod_stav"."popis" != 'přerušen' GROUP BY "organy"."zkratka", "organy"."id_organ", "schuze"."od_schuze", "bod_schuze"."id_schuze" LIMIT 575;

