FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" WHERE "hl_vazby"."typ" != 2 AND "organy"."nazev_organu_en" IS NULL GROUP BY "hl_hlasovani"."cas", "zmatecne"."id_hlasovani", "organy"."id_typ_organu" HAVING AVG("organy"."cl_organ_base") > 7 ORDER BY COUNT("hl_hlasovani"."prihlaseno") DESC, "hl_hlasovani"."cas" ASC LIMIT 650;

SELECT "poslanec"."id_kraj", "hl_poslanec"."id_poslanec", "poslanec"."telefon", "omluvy"."id_organ", "omluvy"."do", COUNT("poslanec"."id_osoba"), SUM("hl_poslanec"."id_hlasovani")
FROM "poslanec" LEFT JOIN "omluvy" ON "poslanec"."id_poslanec" = "omluvy"."id_poslanec" JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" WHERE "hl_poslanec"."id_hlasovani" > 60311 GROUP BY "poslanec"."id_kraj", "hl_poslanec"."id_poslanec", "poslanec"."telefon", "omluvy"."id_organ", "omluvy"."do" ORDER BY "hl_poslanec"."id_poslanec" DESC, "poslanec"."id_kraj" DESC;

SELECT "bod_schuze"."zkratka", "schuze"."id_organ", "schuze"."id_organ", "bod_schuze"."uplny_kon", MIN("schuze"."id_organ")
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "bod_schuze"."zkratka" = 'st.soc.podpora' OR "bod_schuze"."pozvanka" IS NOT NULL OR "bod_schuze"."zkratka" = 'o dobrovolnické službě' OR "schuze"."do_schuze" != '2003-06-10 17' GROUP BY "bod_schuze"."zkratka", "schuze"."id_organ", "schuze"."id_organ", "bod_schuze"."uplny_kon" HAVING MIN("schuze"."id_organ") > 50 ORDER BY "schuze"."id_organ" ASC, "bod_schuze"."zkratka" DESC;

SELECT "typ_organu"."typ_id_typ_org", "typ_organu"."typ_id_typ_org", "typ_organu"."typ_id_typ_org", "organy"."cl_organ_base", MIN("hl_hlasovani"."cislo")
FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "typ_organu"."priorita" >= 5 GROUP BY "typ_organu"."typ_id_typ_org", "typ_organu"."typ_id_typ_org", "typ_organu"."typ_id_typ_org", "organy"."cl_organ_base" ORDER BY "typ_organu"."typ_id_typ_org" DESC, "typ_organu"."typ_id_typ_org" ASC;

