SELECT "hl_hlasovani"."nazev_dlouhy", "organy"."zkratka", "organy"."id_organ", "hl_hlasovani"."id_hlasovani", AVG("organy"."organ_id_organ"), COUNT("schuze"."id_schuze"), AVG("schuze"."id_organ")
FROM "organy" LEFT JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "schuze"."od_schuze" = '2008-10-21 14' AND "hl_hlasovani"."pro" = 125 AND "hl_hlasovani"."cislo" = 107 AND "organy"."id_typ_organu" >= 1 AND "schuze"."schuze" != 70 GROUP BY "hl_hlasovani"."nazev_dlouhy", "organy"."zkratka", "organy"."id_organ", "hl_hlasovani"."id_hlasovani";

