SELECT "organy"."priorita", "omluvy"."id_poslanec", MIN("organy"."cl_organ_base")
FROM "omluvy" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" LEFT JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."psp_telefon" != '2097' AND "organy"."nazev_organu_cz" = 'KLDR' AND "poslanec"."facebook" = 'http://www.facebook.com/heger.leos' AND "poslanec"."ulice" = '\' GROUP BY "organy"."priorita", "omluvy"."id_poslanec" ORDER BY "omluvy"."id_poslanec" ASC, MIN("organy"."cl_organ_base") ASC;

