FROM "hl_zposlanec" JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" >= 58965 AND "hl_zposlanec"."id_hlasovani" != 58576 AND "hl_vazby"."turn" < 87 GROUP BY "hl_hlasovani"."zdrzel", "hl_zposlanec"."id_osoba" ORDER BY "hl_hlasovani"."zdrzel" DESC, AVG("zmatecne"."id_hlasovani") DESC;

