SELECT "zarazeni"."id_osoba", "osoby"."zmena", "hl_hlasovani"."nazev_kratky", AVG("hl_zposlanec"."id_hlasovani")
FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" LEFT JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" LEFT JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."vysledek" = 'R' AND "zarazeni"."od_f" = '25.04.2001' AND "hl_hlasovani"."pro" > 89 AND "hl_hlasovani"."cas" = 'default' GROUP BY "zarazeni"."id_osoba", "osoby"."zmena", "hl_hlasovani"."nazev_kratky" HAVING AVG("hl_zposlanec"."id_hlasovani") > 1 ORDER BY AVG("hl_zposlanec"."id_hlasovani") DESC, "zarazeni"."id_osoba" DESC;

SELECT "organy"."od_organ", "schuze"."od_schuze", "schuze"."aktualizace", "schuze"."id_organ", COUNT("schuze"."id_schuze"), MAX("schuze"."id_schuze")
FROM "schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "schuze"."id_organ" = 170 OR "schuze"."schuze" < 13 OR "schuze"."id_schuze" <= 134 OR "organy"."nazev_organu_cz" = 'Podvýbor pro vězeňství' OR "organy"."zkratka" = 'EKOPO' GROUP BY "organy"."od_organ", "schuze"."od_schuze", "schuze"."aktualizace", "schuze"."id_organ" ORDER BY "schuze"."id_organ" DESC, "organy"."od_organ" DESC LIMIT 883;

SELECT "poslanec"."id_obdobi", "poslanec"."telefon", "poslanec"."id_kraj", SUM("poslanec"."id_osoba"), SUM("pkgps"."delka")
FROM "pkgps" LEFT JOIN "poslanec" ON "pkgps"."id_poslanec" = "poslanec"."id_poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" WHERE "osoby"."id_osoba" = 1652 OR "osoby"."prijmeni" LIKE '%Marek%' OR "poslanec"."ulice" = '\' OR "poslanec"."psc" != '46007' OR "poslanec"."web" = 'http://www.helenalangsadlova.cz/' GROUP BY "poslanec"."id_obdobi", "poslanec"."telefon", "poslanec"."id_kraj" HAVING SUM("poslanec"."id_osoba") > 74 ORDER BY SUM("pkgps"."delka") DESC, "poslanec"."id_obdobi" DESC;

SELECT "zarazeni"."id_osoba", "hl_zposlanec"."id_hlasovani", "poslanec"."ulice", "hl_zposlanec"."id_osoba", COUNT("zarazeni"."id_of")
FROM "zarazeni" LEFT JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "poslanec"."id_obdobi" = 165 AND "zarazeni"."do_f" != '20.08.2021' AND "poslanec"."telefon" != '\' AND "zarazeni"."do_f" IS NOT NULL GROUP BY "zarazeni"."id_osoba", "hl_zposlanec"."id_hlasovani", "poslanec"."ulice", "hl_zposlanec"."id_osoba" HAVING COUNT("zarazeni"."id_of") > 99 ORDER BY "zarazeni"."id_osoba" DESC, COUNT("zarazeni"."id_of") ASC LIMIT 866;

SELECT "typ_funkce"."id_typ_org", "typ_organu"."nazev_typ_org_en", "typ_organu"."typ_org_obecny", "typ_organu"."priorita", "typ_organu"."id_typ_org", MIN("funkce"."id_organ")
FROM "typ_funkce" JOIN "typ_organu" ON "typ_funkce"."id_typ_org" = "typ_organu"."id_typ_org" LEFT JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "funkce"."id_organ" >= 1170 AND "typ_organu"."nazev_typ_org_en" IS NULL AND "funkce"."priorita" = 673 AND "funkce"."priorita" < 1 GROUP BY "typ_funkce"."id_typ_org", "typ_organu"."nazev_typ_org_en", "typ_organu"."typ_org_obecny", "typ_organu"."priorita", "typ_organu"."id_typ_org" HAVING MIN("funkce"."id_organ") > 12 ORDER BY "typ_organu"."nazev_typ_org_en" ASC, "typ_organu"."id_typ_org" ASC LIMIT 750;

