FROM "osoby" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" WHERE "osoby"."zmena" IS NOT NULL GROUP BY "zarazeni"."od_o", "zarazeni"."do_o", "osoby"."prijmeni" HAVING COUNT("hl_poslanec"."id_poslanec") > 36 ORDER BY COUNT("hl_poslanec"."id_poslanec") ASC, COUNT("zarazeni"."id_osoba") ASC;

