FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "osoby" ON "hl_zposlanec"."id_osoba" = "osoby"."id_osoba" WHERE "osoby"."id_osoba" >= 343 AND "hl_vazby"."typ" >= -3 AND "hl_vazby"."turn" >= 39 AND "hl_vazby"."turn" < 43 AND "hl_zposlanec"."mode" = 10 GROUP BY "hl_vazby"."typ", "hl_vazby"."id_hlasovani", "hl_vazby"."typ", "hl_hlasovani"."id_hlasovani", "hl_hlasovani"."cas" ORDER BY AVG("osoby"."id_osoba") ASC, "hl_hlasovani"."cas" ASC;

