FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" = 61217 GROUP BY "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "hl_hlasovani"."zdrzel";

