SELECT "hl_hlasovani"."datum", "hl_hlasovani"."nazev_dlouhy", "hl_hlasovani"."id_organ", "hl_hlasovani"."nehlasoval", SUM("hl_hlasovani"."prihlaseno"), MIN("hl_hlasovani"."cislo"), MAX("hl_vazby"."id_hlasovani")
