SELECT "typ_organu"."typ_id_typ_org", "typ_organu"."id_typ_org", "funkce"."nazev_funkce_cz", "funkce"."nazev_funkce_cz", AVG("typ_funkce"."typ_funkce_obecny"), AVG("funkce"."id_organ"), MAX("funkce"."id_organ")
FROM "typ_funkce" JOIN "typ_organu" ON "typ_funkce"."id_typ_org" = "typ_organu"."id_typ_org" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "funkce"."nazev_funkce_cz" LIKE '%Místopředseda klubu SPR-RSČ%' AND "typ_funkce"."typ_funkce_cz" = 'Předseda' AND "typ_organu"."id_typ_org" < 65 AND "typ_funkce"."typ_funkce_obecny" = 1 AND "typ_organu"."priorita" < 55 GROUP BY "typ_organu"."typ_id_typ_org", "typ_organu"."id_typ_org", "funkce"."nazev_funkce_cz", "funkce"."nazev_funkce_cz" HAVING AVG("funkce"."id_organ") > 22 ORDER BY "typ_organu"."id_typ_org" ASC, "typ_organu"."typ_id_typ_org" ASC;

SELECT "poslanec"."id_osoba", "omluvy"."den", "omluvy"."od", "omluvy"."den", COUNT("omluvy"."id_poslanec"), MAX("poslanec"."id_obdobi"), MIN("poslanec"."id_kraj")
FROM "omluvy" LEFT JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."telefon" != '\' OR "omluvy"."do" = '13:39' OR "poslanec"."facebook" IS NOT NULL OR "omluvy"."od" LIKE '%13:30%' OR "omluvy"."od" = '18:30' GROUP BY "poslanec"."id_osoba", "omluvy"."den", "omluvy"."od", "omluvy"."den" ORDER BY COUNT("omluvy"."id_poslanec") DESC, "poslanec"."id_osoba" ASC;

SELECT "funkce"."nazev_funkce_cz", "organy"."zkratka", "organy"."zkratka", "funkce"."id_organ", "organy"."nazev_organu_cz", SUM("funkce"."id_organ"), AVG("funkce"."id_typ_funkce")
FROM "organy" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "organy"."cl_organ_base" != 1 AND "typ_funkce"."typ_funkce_cz" != 'Člen vlády' AND "funkce"."id_organ" >= 842 AND "funkce"."nazev_funkce_cz" != 'Místopředseda' GROUP BY "funkce"."nazev_funkce_cz", "organy"."zkratka", "organy"."zkratka", "funkce"."id_organ", "organy"."nazev_organu_cz" ORDER BY "organy"."zkratka" DESC, SUM("funkce"."id_organ") DESC;

