FROM "hl_zposlanec" LEFT JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" > 59671 GROUP BY "zmatecne"."id_hlasovani", "hl_zposlanec"."id_osoba", "hl_hlasovani"."id_hlasovani", "hl_hlasovani"."id_organ" HAVING SUM("hl_check"."mode") > 87 ORDER BY "zmatecne"."id_hlasovani" DESC, SUM("hl_check"."mode") ASC;

SELECT "organy"."organ_id_organ", "organy"."zkratka", AVG("bod_stav"."id_bod_stav"), MIN("bod_schuze"."id_bod"), MIN("organy"."cl_organ_base")
FROM "bod_schuze" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_stav"."id_bod_stav" <= 1 GROUP BY "organy"."organ_id_organ", "organy"."zkratka" HAVING AVG("bod_stav"."id_bod_stav") > 62 ORDER BY "organy"."zkratka" ASC, MIN("organy"."cl_organ_base") ASC;

