FROM "pkgps" LEFT JOIN "poslanec" ON "pkgps"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."ulice" LIKE '%\%' AND "poslanec"."psp_telefon" = '2097' AND "poslanec"."id_kraj" < 591 GROUP BY "poslanec"."fax", "poslanec"."id_osoba", "poslanec"."id_osoba", "pkgps"."sirka" HAVING AVG("poslanec"."id_poslanec") > 22 ORDER BY "poslanec"."fax" ASC, "pkgps"."sirka" DESC;

