FROM "omluvy" LEFT JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" WHERE "organy"."priorita" = '80' GROUP BY "organy"."nazev_organu_cz", "osoby"."prijmeni", "poslanec"."web", "organy"."priorita", "omluvy"."den" ORDER BY "organy"."priorita" ASC, "organy"."nazev_organu_cz" DESC;

