SELECT "hl_vazby"."id_hlasovani", "hl_vazby"."turn", "hl_check"."id_hlasovani", "hl_vazby"."turn", "hl_hlasovani"."proti", COUNT("hl_vazby"."id_hlasovani"), MIN("hl_vazby"."typ")
