FROM "typ_funkce" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "funkce"."priorita" = -4 AND "funkce"."id_typ_funkce" = 11 AND "typ_funkce"."typ_funkce_cz" != 'Viceprezident' AND "funkce"."priorita" > 2 AND "typ_funkce"."id_typ_funkce" > 98 GROUP BY "typ_funkce"."typ_funkce_obecny", "typ_funkce"."priorita", "typ_funkce"."id_typ_org", "funkce"."id_organ", "funkce"."id_funkce" HAVING AVG("typ_funkce"."priorita") > 84 ORDER BY "typ_funkce"."priorita" ASC, "funkce"."id_funkce" DESC;

