FROM "omluvy" LEFT JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" WHERE "organy"."id_typ_organu" = 6 AND "organy"."organ_id_organ" != 551 AND "omluvy"."id_poslanec" < 1185 AND "poslanec"."obec" = 'Praha 2' AND "omluvy"."id_poslanec" > 999 GROUP BY "hl_poslanec"."id_poslanec", "hl_poslanec"."id_poslanec", "omluvy"."id_poslanec", "hl_poslanec"."vysledek" HAVING MIN("omluvy"."id_poslanec") > 15 ORDER BY SUM("organy"."organ_id_organ") DESC, "hl_poslanec"."id_poslanec" DESC;

