FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."prihlaseno" != 166 AND "hl_hlasovani"."cislo" < 119 GROUP BY "hl_hlasovani"."kvorum", "hl_check"."id_h3", "hl_check"."id_hlasovani" HAVING SUM("hl_hlasovani"."proti") > 37 ORDER BY "hl_check"."id_h3" ASC, SUM("hl_hlasovani"."proti") DESC;

