SELECT "organy"."zkratka", "organy"."organ_id_organ", MAX("organy"."id_typ_organu"), MIN("bod_schuze"."bod")
FROM "bod_schuze" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "organy"."do_organ" IS NULL OR "schuze"."od_schuze" LIKE '%2007-04-24 14%' OR "schuze"."aktualizace" = '2000-06-26 12:00' OR "bod_schuze"."pozvanka" != '1' GROUP BY "organy"."zkratka", "organy"."organ_id_organ" LIMIT 637;

SELECT "pkgps"."delka", "pkgps"."adresa", AVG("osoby"."id_osoba"), MIN("poslanec"."id_kraj"), MAX("poslanec"."id_kandidatka")
FROM "pkgps" JOIN "poslanec" ON "pkgps"."id_poslanec" = "poslanec"."id_poslanec" JOIN "hl_poslanec" ON "poslanec"."id_poslanec" = "hl_poslanec"."id_poslanec" LEFT JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" WHERE "pkgps"."delka" > 16.88383142860965 GROUP BY "pkgps"."delka", "pkgps"."adresa" ORDER BY "pkgps"."adresa" DESC, "pkgps"."delka" DESC;

SELECT "typ_organu"."typ_id_typ_org", "typ_organu"."nazev_typ_org_en", "organy"."zkratka", "typ_organu"."nazev_typ_org_cz", "organy"."od_organ", MAX("typ_organu"."priorita")
FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" WHERE "typ_organu"."nazev_typ_org_cz" != 'Orgány Registru' GROUP BY "typ_organu"."typ_id_typ_org", "typ_organu"."nazev_typ_org_en", "organy"."zkratka", "typ_organu"."nazev_typ_org_cz", "organy"."od_organ" HAVING MAX("typ_organu"."priorita") > 7 LIMIT 510;

SELECT "bod_schuze"."pozvanka", "bod_stav"."id_bod_stav", "organy"."nazev_organu_cz", "organy"."cl_organ_base", "schuze"."aktualizace", MIN("bod_stav"."id_bod_stav")
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_schuze"."poznamka" IS NOT NULL AND "bod_stav"."id_bod_stav" <= 1 GROUP BY "bod_schuze"."pozvanka", "bod_stav"."id_bod_stav", "organy"."nazev_organu_cz", "organy"."cl_organ_base", "schuze"."aktualizace" HAVING MIN("bod_stav"."id_bod_stav") > 54 ORDER BY "bod_schuze"."pozvanka" DESC, "organy"."cl_organ_base" DESC;

SELECT "schuze"."od_schuze", "schuze"."do_schuze", "schuze_stav"."text_dt", MIN("schuze"."schuze"), MAX("bod_schuze"."bod"), AVG("bod_schuze"."id_schuze")
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "schuze"."schuze" > 37 AND "bod_schuze"."id_typ" != '5' GROUP BY "schuze"."od_schuze", "schuze"."do_schuze", "schuze_stav"."text_dt";

SELECT "organy"."organ_id_organ", "typ_organu"."priorita", "organy"."do_organ", MIN("typ_organu"."id_typ_org")
FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" WHERE "organy"."od_organ" = '15.11.1925' AND "organy"."nazev_organu_cz" = 'Výbor pro obranu a bezpečnost' AND "typ_organu"."typ_id_typ_org" != '85' GROUP BY "organy"."organ_id_organ", "typ_organu"."priorita", "organy"."do_organ" HAVING MIN("typ_organu"."id_typ_org") > 68 ORDER BY "organy"."do_organ" DESC, "organy"."organ_id_organ" DESC;

