FROM "typ_funkce" LEFT JOIN "typ_organu" ON "typ_funkce"."id_typ_org" = "typ_organu"."id_typ_org" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "typ_funkce"."typ_funkce_obecny" >= 1 AND "typ_organu"."nazev_typ_org_cz" != 'Parlamentní shromáždění NATO' AND "typ_organu"."priorita" != 146 GROUP BY "typ_funkce"."id_typ_org", "funkce"."id_organ", "typ_organu"."nazev_typ_org_en", "funkce"."nazev_funkce_cz", "typ_funkce"."typ_funkce_en" LIMIT 499;

