SELECT "hl_hlasovani"."kvorum", "zmatecne"."id_hlasovani", SUM("zmatecne"."id_hlasovani"), SUM("hl_vazby"."id_hlasovani")
FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_hlasovani"."zdrzel" = 4 AND "hl_vazby"."id_hlasovani" >= 61092 AND "hl_vazby"."typ" <= 0 AND "hl_vazby"."typ" != -3 AND "hl_zposlanec"."id_osoba" != 6202 GROUP BY "hl_hlasovani"."kvorum", "zmatecne"."id_hlasovani" ORDER BY SUM("hl_vazby"."id_hlasovani") ASC, "hl_hlasovani"."kvorum" ASC;

SELECT "osoby"."pohlavi", "osoby"."zmena", "zarazeni"."od_f", "zarazeni"."od_o", AVG("osoby"."id_osoba"), COUNT("zarazeni"."id_osoba"), AVG("osoby"."id_osoba")
FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" WHERE "zarazeni"."do_f" != '27.07.2021' AND "zarazeni"."do_o" != '1998-06-19 00' GROUP BY "osoby"."pohlavi", "osoby"."zmena", "zarazeni"."od_f", "zarazeni"."od_o";

