SELECT "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", "hl_vazby"."id_hlasovani", "hl_vazby"."id_hlasovani", "zmatecne"."id_hlasovani", AVG("hl_vazby"."typ")
