FROM "hl_poslanec" LEFT JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."id_obdobi" < 166 AND "poslanec"."facebook" != '\' GROUP BY "hl_poslanec"."id_poslanec", "hl_poslanec"."id_hlasovani", "hl_poslanec"."vysledek" ORDER BY MIN("hl_poslanec"."id_hlasovani") ASC, "hl_poslanec"."id_poslanec" ASC LIMIT 680;

