SELECT "bod_stav"."id_bod_stav", "bod_schuze"."id_sd", "bod_schuze"."pozn2", "bod_stav"."popis", MIN("bod_stav"."id_bod_stav"), MIN("bod_schuze"."id_bod_stav"), MAX("bod_schuze"."id_bod_stav")
FROM "bod_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "bod_schuze"."bod" > 243 AND "bod_stav"."id_bod_stav" > 4 AND "bod_stav"."popis" = 'neprojednatelný' GROUP BY "bod_stav"."id_bod_stav", "bod_schuze"."id_sd", "bod_schuze"."pozn2", "bod_stav"."popis" LIMIT 200;

