FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_schuze"."id_schuze" = 246 AND "bod_schuze"."id_bod_stav" = 1 GROUP BY "bod_stav"."id_bod_stav", "organy"."organ_id_organ", "schuze"."od_schuze", "bod_stav"."popis", "schuze"."do_schuze" HAVING SUM("schuze"."id_organ") > 93 ORDER BY "organy"."organ_id_organ" ASC, "schuze"."do_schuze" DESC LIMIT 816;

