SELECT "organy"."id_typ_organu", "typ_organu"."id_typ_org", "typ_organu"."nazev_typ_org_cz", MIN("organy"."id_typ_organu"), COUNT("funkce"."id_typ_funkce"), MAX("typ_funkce"."id_typ_funkce")
FROM "typ_organu" JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "typ_funkce"."typ_funkce_cz" != '1. místopředseda' AND "funkce"."id_organ" <= 296 AND "organy"."id_typ_organu" >= 1 AND "funkce"."id_funkce" >= 544 GROUP BY "organy"."id_typ_organu", "typ_organu"."id_typ_org", "typ_organu"."nazev_typ_org_cz" ORDER BY COUNT("funkce"."id_typ_funkce") ASC, MAX("typ_funkce"."id_typ_funkce") DESC LIMIT 36;

SELECT "schuze"."id_schuze", "bod_schuze"."uplny_naz", "bod_stav"."popis", MAX("organy"."id_organ"), SUM("organy"."id_organ"), MAX("bod_schuze"."bod")
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_schuze"."pozvanka" IS NOT NULL GROUP BY "schuze"."id_schuze", "bod_schuze"."uplny_naz", "bod_stav"."popis" ORDER BY "bod_schuze"."uplny_naz" DESC, MAX("bod_schuze"."bod") DESC;

SELECT "hl_hlasovani"."bod", "omluvy"."id_organ", "hl_hlasovani"."vysledek", MAX("hl_hlasovani"."cislo")
FROM "poslanec" LEFT JOIN "omluvy" ON "poslanec"."id_poslanec" = "omluvy"."id_poslanec" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "omluvy"."do" = '13:39' AND "omluvy"."od" IS NOT NULL AND "organy"."id_typ_organu" > 25 AND "hl_hlasovani"."cislo" <= 131 AND "hl_hlasovani"."nazev_dlouhy" LIKE '%Vl.n.z. o změnách zák. v oblasti finančního trhu - EU%' GROUP BY "hl_hlasovani"."bod", "omluvy"."id_organ", "hl_hlasovani"."vysledek" ORDER BY MAX("hl_hlasovani"."cislo") DESC, "hl_hlasovani"."bod" DESC LIMIT 813;

SELECT "typ_funkce"."typ_funkce_en", "typ_funkce"."typ_funkce_cz", "typ_funkce"."typ_funkce_obecny", SUM("typ_organu"."id_typ_org"), COUNT("schuze"."id_organ"), MAX("schuze"."id_schuze")
FROM "typ_organu" LEFT JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" LEFT JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "schuze"."id_organ" <= 170 AND "typ_funkce"."id_typ_org" >= 46 AND "schuze"."od_schuze" = '1996-04-16 14' GROUP BY "typ_funkce"."typ_funkce_en", "typ_funkce"."typ_funkce_cz", "typ_funkce"."typ_funkce_obecny" HAVING MAX("schuze"."id_schuze") > 81;

SELECT "schuze_stav"."id_schuze", "bod_schuze"."id_bod_stav", "schuze"."od_schuze", "bod_schuze"."id_schuze", MIN("schuze_stav"."id_schuze")
FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "schuze_stav"."text_dt" = '12. prosince, 10 minut po ukončení 23. schůze' AND "schuze"."aktualizace" != '2000-06-26 12:00' GROUP BY "schuze_stav"."id_schuze", "bod_schuze"."id_bod_stav", "schuze"."od_schuze", "bod_schuze"."id_schuze" HAVING MIN("schuze_stav"."id_schuze") > 79 LIMIT 926;

SELECT "hl_hlasovani"."nazev_kratky", "hl_hlasovani"."id_hlasovani", "hl_hlasovani"."datum", "hl_check"."turn", "hl_check"."id_h3", MAX("hl_check"."id_hlasovani")
FROM "hl_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_hlasovani"."datum" = '2023-10-24' AND "hl_check"."mode" > 0 AND "hl_check"."id_h2" IS NOT NULL GROUP BY "hl_hlasovani"."nazev_kratky", "hl_hlasovani"."id_hlasovani", "hl_hlasovani"."datum", "hl_check"."turn", "hl_check"."id_h3" LIMIT 791;

