FROM "funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "funkce"."id_typ_funkce" >= 9 AND "funkce"."id_funkce" <= 716 AND "organy"."nazev_organu_cz" LIKE '%Slovensko%' GROUP BY "funkce"."id_funkce", "funkce"."id_organ";

SELECT "bod_schuze"."id_tisk", "bod_schuze"."id_sd", "bod_stav"."popis", "bod_schuze"."druh_bodu", MAX("bod_schuze"."id_bod_stav"), MAX("bod_schuze"."bod")
FROM "bod_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "bod_schuze"."poznamka" = 'St 28.11.-3.bod' AND "bod_stav"."id_bod_stav" != 3 AND "bod_schuze"."id_tisk" = '39035' GROUP BY "bod_schuze"."id_tisk", "bod_schuze"."id_sd", "bod_stav"."popis", "bod_schuze"."druh_bodu" HAVING MAX("bod_schuze"."id_bod_stav") > 30 ORDER BY "bod_stav"."popis" DESC, MAX("bod_schuze"."bod") ASC;

SELECT "hl_hlasovani"."prihlaseno", "hl_hlasovani"."nazev_dlouhy", AVG("hl_hlasovani"."id_hlasovani")
FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_vazby"."turn" != 72 GROUP BY "hl_hlasovani"."prihlaseno", "hl_hlasovani"."nazev_dlouhy" HAVING AVG("hl_hlasovani"."id_hlasovani") > 56 ORDER BY AVG("hl_hlasovani"."id_hlasovani") DESC, "hl_hlasovani"."prihlaseno" ASC;

SELECT "osoby"."prijmeni", "hl_poslanec"."id_poslanec", "pkgps"."id_poslanec", COUNT("poslanec"."foto")
FROM "hl_poslanec" JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "pkgps"."delka" != 18.319394586580543 AND "osoby"."zmena" = '03.08.2000' AND "osoby"."zmena" IS NULL AND "hl_poslanec"."id_poslanec" = 1394 GROUP BY "osoby"."prijmeni", "hl_poslanec"."id_poslanec", "pkgps"."id_poslanec" ORDER BY "pkgps"."id_poslanec" ASC, "osoby"."prijmeni" ASC LIMIT 223;

SELECT "bod_stav"."id_bod_stav", "bod_schuze"."druh_bodu", SUM("bod_stav"."id_bod_stav"), AVG("bod_schuze"."bod"), AVG("bod_stav"."id_bod_stav")
FROM "bod_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "organy"."zkratka" = 'PS' GROUP BY "bod_stav"."id_bod_stav", "bod_schuze"."druh_bodu" HAVING AVG("bod_stav"."id_bod_stav") > 13 ORDER BY AVG("bod_schuze"."bod") ASC, "bod_stav"."id_bod_stav" DESC LIMIT 711;

