SELECT "hl_hlasovani"."zdrzel", "hl_zposlanec"."id_osoba", "hl_zposlanec"."mode", "hl_hlasovani"."vysledek", SUM("hl_hlasovani"."pro"), AVG("hl_hlasovani"."kvorum"), MIN("hl_vazby"."id_hlasovani")
