FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "organy"."zkratka" = 'Bulhar' AND "organy"."organ_id_organ" >= 57 AND "hl_hlasovani"."zdrzel" != 19 AND "organy"."cl_organ_base" < 3 GROUP BY "hl_check"."id_h2", "hl_check"."id_hlasovani", "organy"."do_organ" ORDER BY "organy"."do_organ" DESC, MIN("hl_vazby"."id_hlasovani") DESC LIMIT 967;

