FROM "hl_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" >= 58804 GROUP BY "hl_hlasovani"."nazev_dlouhy", "hl_zposlanec"."id_osoba", "hl_check"."id_h3", "hl_hlasovani"."nazev_dlouhy", "hl_hlasovani"."cislo" ORDER BY "hl_hlasovani"."cislo" DESC, COUNT("hl_hlasovani"."proti") ASC LIMIT 985;

