FROM "funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" WHERE "funkce"."id_typ_funkce" >= 16 AND "funkce"."id_organ" <= 30 AND "funkce"."nazev_funkce_cz" LIKE '%Místopředseda%' GROUP BY "funkce"."id_typ_funkce", "organy"."do_organ", "organy"."priorita", "funkce"."id_organ" ORDER BY "organy"."priorita" ASC, "funkce"."id_typ_funkce" ASC;

SELECT "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", SUM("zmatecne"."id_hlasovani"), MAX("zmatecne"."id_hlasovani"), SUM("hl_hlasovani"."id_organ")
FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "zmatecne"."id_hlasovani" = 61095 AND "zmatecne"."id_hlasovani" >= 61079 AND "zmatecne"."id_hlasovani" != 60789 GROUP BY "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani" HAVING SUM("hl_hlasovani"."id_organ") > 64 ORDER BY "zmatecne"."id_hlasovani" ASC, MAX("zmatecne"."id_hlasovani") DESC LIMIT 358;

SELECT "organy"."do_organ", "schuze"."id_organ", "schuze"."od_schuze", "zmatecne"."id_hlasovani", "schuze"."schuze", AVG("schuze"."id_organ"), MIN("schuze"."schuze"), MAX("zmatecne"."id_hlasovani")
FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "organy"."nazev_organu_cz" LIKE '%Nezařazení%' AND "schuze"."od_schuze" = '2009-03-03 14' AND "zmatecne"."id_hlasovani" > 59615 AND "organy"."id_typ_organu" != 35 AND "schuze"."id_schuze" <= 255 GROUP BY "organy"."do_organ", "schuze"."id_organ", "schuze"."od_schuze", "zmatecne"."id_hlasovani", "schuze"."schuze" HAVING MIN("schuze"."schuze") > 78 LIMIT 933;

SELECT "funkce"."id_funkce", "schuze"."schuze", "schuze"."od_schuze", "funkce"."priorita", AVG("funkce"."id_organ"), AVG("schuze"."id_organ"), MAX("funkce"."id_typ_funkce")
FROM "funkce" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" LEFT JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "organy"."nazev_organu_cz" LIKE '%Volební komise Poslanecké sněmovny%' OR "typ_funkce"."id_typ_funkce" < 108 OR "organy"."od_organ" = '18.01.2012' OR "schuze"."id_organ" < 170 GROUP BY "funkce"."id_funkce", "schuze"."schuze", "schuze"."od_schuze", "funkce"."priorita" ORDER BY "funkce"."priorita" DESC, AVG("funkce"."id_organ") DESC;

SELECT "bod_schuze"."id_typ", "schuze"."do_schuze", AVG("bod_stav"."id_bod_stav"), MAX("bod_stav"."id_bod_stav")
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "bod_schuze"."uplny_naz" != 'Návrh poslanců Jiřího Dolejše, Petra Braného, Miloslavy Vostré, Vojtěcha Filipa a Pavla Kováčika na vydání zákona o majetkovém přiznání a o změně zákona č. 586/1992 Sb., o daních z příjmů, ve znění pozdějších předpisů (zákon o majetkovém přiznání)' AND "schuze"."id_organ" = 165 GROUP BY "bod_schuze"."id_typ", "schuze"."do_schuze" ORDER BY AVG("bod_stav"."id_bod_stav") DESC, "schuze"."do_schuze" DESC LIMIT 271;

SELECT "zarazeni"."id_osoba", "zarazeni"."cl_funkce", "zarazeni"."do_o", "osoby"."id_osoba", "osoby"."pohlavi", COUNT("osoby"."id_osoba"), MIN("zarazeni"."cl_funkce")
FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" WHERE "osoby"."narozeni" LIKE '%21.08.1945%' AND "zarazeni"."id_of" >= 69 GROUP BY "zarazeni"."id_osoba", "zarazeni"."cl_funkce", "zarazeni"."do_o", "osoby"."id_osoba", "osoby"."pohlavi" ORDER BY "osoby"."id_osoba" ASC, "zarazeni"."do_o" ASC;

