SELECT "osoby"."za", "osoby"."pohlavi", "poslanec"."web", "poslanec"."fax", "osoby"."prijmeni", MIN("osoby"."id_osoba"), SUM("osoby"."id_osoba"), COUNT("poslanec"."id_poslanec")
FROM "osoby" JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "poslanec"."id_obdobi" != 168 AND "osoby"."id_osoba" = 1196 GROUP BY "osoby"."za", "osoby"."pohlavi", "poslanec"."web", "poslanec"."fax", "osoby"."prijmeni" HAVING SUM("osoby"."id_osoba") > 2 ORDER BY "poslanec"."fax" ASC, MIN("osoby"."id_osoba") DESC LIMIT 835;

