FROM "hl_zposlanec" LEFT JOIN "osoby" ON "hl_zposlanec"."id_osoba" = "osoby"."id_osoba" LEFT JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "osoby"."zmena" = '07.06.1981' AND "pkgps"."sirka" != 49.842258310561014 AND "pkgps"."delka" >= 13.83505380839098 AND "pkgps"."adresa" = 'Malostranské nám. 266/5; Praha 1; 11800' GROUP BY "hl_zposlanec"."id_osoba", "pkgps"."delka" LIMIT 987;

SELECT "funkce"."id_typ_funkce", "organy"."zkratka", MIN("funkce"."id_typ_funkce"), MAX("funkce"."id_typ_funkce"), SUM("organy"."cl_organ_base")
FROM "organy" LEFT JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "funkce"."id_funkce" > 435 GROUP BY "funkce"."id_typ_funkce", "organy"."zkratka" HAVING MAX("funkce"."id_typ_funkce") > 33;

SELECT "schuze_stav"."text_dt", "schuze_stav"."typ", "schuze_stav"."text_dt", "bod_schuze"."poznamka", COUNT("schuze"."id_schuze"), COUNT("bod_schuze"."id_bod_stav")
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "schuze_stav"."text_st" = 'návrh prezidentu republiky na rozpuštění PS' AND "schuze_stav"."typ" != '2' AND "schuze_stav"."stav" >= -6 AND "schuze_stav"."text_dt" = '10 minut po přerušení 20. schůze PS' GROUP BY "schuze_stav"."text_dt", "schuze_stav"."typ", "schuze_stav"."text_dt", "bod_schuze"."poznamka" ORDER BY "schuze_stav"."text_dt" ASC, "bod_schuze"."poznamka" ASC;

SELECT "schuze"."id_schuze", "schuze_stav"."text_st", "schuze"."do_schuze", "schuze_stav"."typ", COUNT("schuze_stav"."stav"), MAX("schuze"."id_schuze")
