FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_schuze"."uplny_kon" = '/sněmovní tisk 583/' AND "schuze_stav"."text_st" IS NULL AND "bod_schuze"."poznamka" IS NOT NULL AND "organy"."cl_organ_base" >= 2 AND "organy"."cl_organ_base" >= -5 GROUP BY "schuze_stav"."tm_line", "organy"."id_typ_organu", "organy"."nazev_organu_en", "bod_schuze"."pozvanka", "organy"."od_organ" LIMIT 510;

