FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_hlasovani"."nazev_kratky" = 'předseda výboru' AND "hl_check"."mode" < 0 GROUP BY "zmatecne"."id_hlasovani", "hl_hlasovani"."cislo", "hl_check"."id_h2", "zmatecne"."id_hlasovani" HAVING MAX("hl_zposlanec"."id_osoba") > 18 ORDER BY "hl_check"."id_h2" ASC, "zmatecne"."id_hlasovani" ASC LIMIT 976;

SELECT "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani", SUM("hl_vazby"."id_hlasovani"), SUM("zmatecne"."id_hlasovani"), MIN("zmatecne"."id_hlasovani")
FROM "hl_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" WHERE "hl_vazby"."turn" < 130 AND "hl_hlasovani"."proti" >= 161 AND "hl_hlasovani"."proti" < 1 AND "hl_zposlanec"."mode" <= 1 GROUP BY "zmatecne"."id_hlasovani", "zmatecne"."id_hlasovani" HAVING SUM("zmatecne"."id_hlasovani") > 45 ORDER BY SUM("hl_vazby"."id_hlasovani") DESC, "zmatecne"."id_hlasovani" DESC;

SELECT "omluvy"."id_poslanec", "omluvy"."den", "omluvy"."id_poslanec", "poslanec"."id_poslanec", "poslanec"."telefon", COUNT("poslanec"."id_kandidatka"), MAX("omluvy"."id_organ")
