FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "organy"."cl_organ_base" < -10 OR "schuze"."aktualizace" LIKE '%2011-06-21 21:21%' GROUP BY "organy"."do_organ", "schuze"."do_schuze", "bod_schuze"."id_bod_stav" LIMIT 39;

SELECT "bod_schuze"."druh_bodu", "organy"."od_organ", "organy"."nazev_organu_en", "bod_stav"."id_bod_stav", "bod_stav"."id_bod_stav", SUM("bod_stav"."id_bod_stav"), COUNT("bod_schuze"."id_schuze"), COUNT("bod_stav"."id_bod_stav")
FROM "bod_stav" JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_stav"."id_bod_stav" != 3 AND "bod_stav"."popis" = 'neprojednán' GROUP BY "bod_schuze"."druh_bodu", "organy"."od_organ", "organy"."nazev_organu_en", "bod_stav"."id_bod_stav", "bod_stav"."id_bod_stav";

