FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."id_organ" <= 5769 AND "hl_vazby"."turn" < 18 AND "hl_hlasovani"."id_hlasovani" <= 60891 AND "hl_vazby"."id_hlasovani" = 61688 AND "hl_hlasovani"."nehlasoval" > 3 GROUP BY "hl_hlasovani"."zdrzel", "hl_vazby"."typ";

