FROM "schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "schuze_stav"."tm_line" IS NOT NULL AND "bod_stav"."popis" = 'jiz projednan' AND "bod_stav"."popis" != 'jiz projednan' GROUP BY "bod_stav"."id_bod_stav", "bod_schuze"."rj", "schuze_stav"."id_schuze" ORDER BY AVG("bod_schuze"."id_bod") ASC, "schuze_stav"."id_schuze" DESC LIMIT 396;

SELECT "hl_zposlanec"."id_hlasovani", "osoby"."za", "hl_hlasovani"."zdrzel", "hl_vazby"."typ", "hl_hlasovani"."prihlaseno", MIN("hl_vazby"."id_hlasovani")
FROM "hl_zposlanec" JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" LEFT JOIN "osoby" ON "hl_zposlanec"."id_osoba" = "osoby"."id_osoba" WHERE "hl_hlasovani"."bod" < 2 OR "hl_zposlanec"."id_hlasovani" < 60729 GROUP BY "hl_zposlanec"."id_hlasovani", "osoby"."za", "hl_hlasovani"."zdrzel", "hl_vazby"."typ", "hl_hlasovani"."prihlaseno" ORDER BY "hl_vazby"."typ" DESC, "hl_hlasovani"."zdrzel" ASC;

SELECT "funkce"."priorita", "organy"."priorita", COUNT("organy"."cl_organ_base"), SUM("hl_check"."turn"), SUM("hl_check"."id_hlasovani")
FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "organy"."od_organ" != '30.09.1998' AND "organy"."priorita" LIKE '%250%' AND "organy"."zkratka" != 'PZS' AND "hl_hlasovani"."nehlasoval" <= 1 GROUP BY "funkce"."priorita", "organy"."priorita" ORDER BY COUNT("organy"."cl_organ_base") DESC, "funkce"."priorita" DESC;

SELECT "osoby"."pohlavi", "osoby"."umrti", "zarazeni"."cl_funkce", "zarazeni"."id_of", "zarazeni"."cl_funkce", COUNT("poslanec"."id_kraj")
FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "zarazeni"."id_of" > 188 AND "poslanec"."obec" != '\' AND "osoby"."pohlavi" = 'Z' AND "osoby"."jmeno" != 'Hacaj' AND "osoby"."pohlavi" != 'Z' GROUP BY "osoby"."pohlavi", "osoby"."umrti", "zarazeni"."cl_funkce", "zarazeni"."id_of", "zarazeni"."cl_funkce" HAVING COUNT("poslanec"."id_kraj") > 14 ORDER BY "zarazeni"."id_of" ASC, COUNT("poslanec"."id_kraj") ASC;

SELECT "organy"."nazev_organu_en", "hl_zposlanec"."mode", "hl_hlasovani"."cas", MIN("organy"."id_organ")
FROM "hl_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_zposlanec"."mode" != 5 GROUP BY "organy"."nazev_organu_en", "hl_zposlanec"."mode", "hl_hlasovani"."cas" ORDER BY "organy"."nazev_organu_en" DESC, "hl_zposlanec"."mode" DESC LIMIT 122;

SELECT "hl_vazby"."turn", "hl_hlasovani"."prihlaseno", "hl_hlasovani"."vysledek", "hl_vazby"."turn", AVG("hl_hlasovani"."kvorum"), MIN("hl_hlasovani"."zdrzel"), MIN("hl_vazby"."typ")
