SELECT "poslanec"."ulice", "zarazeni"."do_f", "osoby"."id_osoba", "zarazeni"."do_o", AVG("osoby"."id_osoba"), MAX("poslanec"."id_obdobi"), MIN("hl_zposlanec"."id_hlasovani")
