FROM "bod_schuze" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."do_schuze" LIKE '%2007-06-20 12%' AND "schuze"."do_schuze" = '2008-12-10 17' AND "bod_schuze"."uplny_naz" LIKE '%Návrh poslanců Jaromíra Talíře, Taťány Fischerové, Evy Novákové, Anny Čurdové, Ladislava Skopala a Hany Šedivé na vydání zákona o rozhlasových a televizních poplatcích%' AND "schuze"."do_schuze" = '2010-02-12 12' GROUP BY "schuze"."do_schuze", "schuze"."schuze", "bod_schuze"."id_sd" HAVING SUM("schuze"."id_schuze") > 17 ORDER BY "bod_schuze"."id_sd" ASC, "schuze"."do_schuze" ASC LIMIT 182;

SELECT "funkce"."id_organ", "organy"."zkratka", "organy"."nazev_organu_cz", "funkce"."priorita", COUNT("funkce"."id_organ"), AVG("funkce"."id_organ"), MAX("organy"."id_organ")
