SELECT "schuze"."od_schuze", "bod_stav"."id_bod_stav", "bod_schuze"."id_sd", "bod_stav"."id_bod_stav", COUNT("bod_schuze"."id_bod"), MIN("bod_stav"."id_bod_stav")
FROM "bod_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "schuze"."id_organ" >= 170 AND "bod_stav"."id_bod_stav" <= 1 GROUP BY "schuze"."od_schuze", "bod_stav"."id_bod_stav", "bod_schuze"."id_sd", "bod_stav"."id_bod_stav" HAVING MIN("bod_stav"."id_bod_stav") > 75 LIMIT 467;

