SELECT "schuze_stav"."typ", "bod_stav"."id_bod_stav", "schuze_stav"."typ", "bod_schuze"."id_typ", "bod_schuze"."zkratka", MAX("bod_schuze"."bod")
FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" LEFT JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" WHERE "schuze_stav"."tm_line" IS NOT NULL AND "bod_stav"."popis" != 'neprojednatelný' GROUP BY "schuze_stav"."typ", "bod_stav"."id_bod_stav", "schuze_stav"."typ", "bod_schuze"."id_typ", "bod_schuze"."zkratka" HAVING MAX("bod_schuze"."bod") > 88 ORDER BY "bod_schuze"."id_typ" ASC, MAX("bod_schuze"."bod") DESC LIMIT 184;

