FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."schuze" > 6 AND "zmatecne"."id_hlasovani" >= 59267 AND "hl_hlasovani"."zdrzel" < 17 AND "zmatecne"."id_hlasovani" <= 61241 AND "zmatecne"."id_hlasovani" >= 60068 GROUP BY "zmatecne"."id_hlasovani", "hl_hlasovani"."cislo" HAVING MAX("hl_hlasovani"."zdrzel") > 3;

