FROM "zarazeni" JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" LEFT JOIN "poslanec" ON "osoby"."id_osoba" = "poslanec"."id_osoba" WHERE "zarazeni"."od_f" = '09.12.2005' AND "osoby"."za" != 'Ph.D., MPA' GROUP BY "zarazeni"."od_o", "osoby"."umrti", "zarazeni"."id_osoba", "osoby"."prijmeni" HAVING COUNT("zarazeni"."cl_funkce") > 91;

