FROM "organy" JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "organy"."nazev_organu_cz" LIKE '%Stálá komise pro sdělovací prostředky%' AND "typ_organu"."typ_id_typ_org" != '84' GROUP BY "typ_organu"."nazev_typ_org_en", "organy"."id_organ", "organy"."zkratka" HAVING COUNT("organy"."organ_id_organ") > 72 ORDER BY MIN("organy"."id_organ") ASC, "typ_organu"."nazev_typ_org_en" DESC LIMIT 208;

