FROM "organy" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "organy"."cl_organ_base" != -4 AND "organy"."od_organ" = '21.05.1999' AND "organy"."id_organ" != 856 AND "organy"."id_organ" > 239 AND "organy"."do_organ" = '05.04.1994' GROUP BY "funkce"."priorita", "organy"."priorita", "organy"."organ_id_organ" ORDER BY "funkce"."priorita" DESC, "organy"."organ_id_organ" DESC LIMIT 616;

SELECT "osoby"."prijmeni", "pkgps"."adresa", "pkgps"."delka", "hl_poslanec"."id_hlasovani", AVG("hl_poslanec"."id_poslanec"), SUM("osoby"."id_osoba"), MAX("osoby"."id_osoba")
FROM "hl_poslanec" LEFT JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "poslanec"."id_kandidatka" <= 16 AND "osoby"."narozeni" LIKE '%01.01.1900%' AND "osoby"."jmeno" LIKE '%Klein%' AND "hl_poslanec"."vysledek" = 'K' AND "hl_poslanec"."id_poslanec" <= 1369 GROUP BY "osoby"."prijmeni", "pkgps"."adresa", "pkgps"."delka", "hl_poslanec"."id_hlasovani" LIMIT 65;

SELECT "typ_funkce"."typ_funkce_en", "hl_hlasovani"."cislo", "funkce"."id_funkce", COUNT("organy"."id_typ_organu"), SUM("hl_hlasovani"."id_organ"), AVG("hl_hlasovani"."nehlasoval")
FROM "funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "hl_hlasovani"."nazev_dlouhy" = 'Novela z. o obalech - EU' AND "funkce"."priorita" < 3 GROUP BY "typ_funkce"."typ_funkce_en", "hl_hlasovani"."cislo", "funkce"."id_funkce" ORDER BY "hl_hlasovani"."cislo" DESC, "funkce"."id_funkce" ASC LIMIT 20;

SELECT "funkce"."id_organ", "funkce"."id_typ_funkce", "funkce"."id_organ", "typ_funkce"."typ_funkce_en", "typ_funkce"."typ_funkce_en", SUM("funkce"."id_typ_funkce")
FROM "funkce" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "funkce"."priorita" != 912 OR "typ_funkce"."typ_funkce_obecny" = -9 OR "typ_funkce"."typ_funkce_cz" != 'Ministr dopravy' GROUP BY "funkce"."id_organ", "funkce"."id_typ_funkce", "funkce"."id_organ", "typ_funkce"."typ_funkce_en", "typ_funkce"."typ_funkce_en" ORDER BY "funkce"."id_organ" ASC, "typ_funkce"."typ_funkce_en" DESC LIMIT 635;

SELECT "zmatecne"."id_hlasovani", "hl_hlasovani"."kvorum", "schuze"."id_schuze", "zmatecne"."id_hlasovani", COUNT("schuze"."id_organ"), AVG("organy"."organ_id_organ")
FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "zmatecne"."id_hlasovani" <= 60511 AND "hl_hlasovani"."schuze" = 9 AND "organy"."id_organ" >= 768 AND "schuze"."id_schuze" > 91 AND "organy"."zkratka" != 'SZ' GROUP BY "zmatecne"."id_hlasovani", "hl_hlasovani"."kvorum", "schuze"."id_schuze", "zmatecne"."id_hlasovani" ORDER BY AVG("organy"."organ_id_organ") DESC, COUNT("schuze"."id_organ") ASC LIMIT 76;

SELECT "omluvy"."id_poslanec", "organy"."od_organ", MAX("schuze"."id_schuze"), MIN("omluvy"."id_organ"), COUNT("organy"."id_organ")
FROM "organy" LEFT JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "omluvy"."id_poslanec" >= 562 AND "organy"."cl_organ_base" >= -2 AND "omluvy"."den" = '16.07.2014' AND "schuze"."od_schuze" LIKE '%1996-04-16 14%' GROUP BY "omluvy"."id_poslanec", "organy"."od_organ" ORDER BY "omluvy"."id_poslanec" ASC, "organy"."od_organ" DESC LIMIT 637;

SELECT "bod_schuze"."uplny_naz", "bod_schuze"."id_bod", "bod_stav"."id_bod_stav", "bod_stav"."popis", "schuze_stav"."tm_line", MIN("schuze_stav"."stav"), MAX("schuze_stav"."stav"), AVG("schuze_stav"."stav")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" WHERE "bod_stav"."popis" = 'přerušen' OR "schuze_stav"."text_st" IS NULL OR "schuze_stav"."id_schuze" < 209 OR "schuze"."id_organ" = 168 GROUP BY "bod_schuze"."uplny_naz", "bod_schuze"."id_bod", "bod_stav"."id_bod_stav", "bod_stav"."popis", "schuze_stav"."tm_line" HAVING AVG("schuze_stav"."stav") > 88;

SELECT "hl_hlasovani"."cislo", "hl_hlasovani"."prihlaseno", "hl_hlasovani"."vysledek", "hl_vazby"."turn", "hl_vazby"."id_hlasovani", AVG("hl_vazby"."id_hlasovani"), AVG("hl_hlasovani"."prihlaseno")
FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_vazby"."turn" > 247 AND "hl_hlasovani"."nehlasoval" = -5 AND "hl_vazby"."typ" != -9 AND "hl_vazby"."turn" > 108 GROUP BY "hl_hlasovani"."cislo", "hl_hlasovani"."prihlaseno", "hl_hlasovani"."vysledek", "hl_vazby"."turn", "hl_vazby"."id_hlasovani" LIMIT 593;

