SELECT "typ_organu"."nazev_typ_org_en", "funkce"."id_typ_funkce", "funkce"."id_typ_funkce", "funkce"."id_funkce", COUNT("typ_organu"."priorita"), MIN("typ_organu"."priorita"), MAX("funkce"."priorita")
FROM "typ_organu" JOIN "organy" ON "typ_organu"."id_typ_org" = "organy"."id_typ_organu" LEFT JOIN "funkce" ON "organy"."id_organ" = "funkce"."id_organ" WHERE "organy"."cl_organ_base" < 3 AND "funkce"."nazev_funkce_cz" = 'Místopředseda' AND "typ_organu"."nazev_typ_org_en" IS NOT NULL AND "funkce"."nazev_funkce_cz" != 'Místopředseda výboru VSPZ' GROUP BY "typ_organu"."nazev_typ_org_en", "funkce"."id_typ_funkce", "funkce"."id_typ_funkce", "funkce"."id_funkce" ORDER BY MIN("typ_organu"."priorita") ASC, MAX("funkce"."priorita") ASC LIMIT 450;

