FROM "hl_vazby" LEFT JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "hl_hlasovani"."kvorum" > 117 AND "hl_vazby"."id_hlasovani" <= 59199 GROUP BY "organy"."nazev_organu_cz", "hl_vazby"."typ" ORDER BY COUNT("organy"."id_organ") ASC, "organy"."nazev_organu_cz" DESC LIMIT 359;

