FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "bod_schuze"."zkratka" != 'Fin.dohoda pro r.01 KES' AND "schuze_stav"."stav" >= 4 AND "schuze_stav"."id_schuze" >= 431 AND "schuze_stav"."typ" = '2' GROUP BY "schuze_stav"."stav", "schuze_stav"."stav", "schuze"."id_organ" HAVING SUM("schuze"."id_schuze") > 26 ORDER BY "schuze"."id_organ" DESC, SUM("schuze"."id_schuze") DESC LIMIT 100;

