SELECT "typ_organu"."priorita", "typ_organu"."nazev_typ_org_en", "typ_organu"."nazev_typ_org_cz", MIN("typ_funkce"."priorita"), AVG("typ_funkce"."id_typ_funkce"), AVG("typ_funkce"."priorita")
