FROM "osoby" LEFT JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_zposlanec"."mode" > 3 AND "osoby"."pred" LIKE '%Dr.%' GROUP BY "hl_hlasovani"."druh_hlasovani", "osoby"."id_osoba" HAVING SUM("osoby"."id_osoba") > 9 ORDER BY SUM("hl_zposlanec"."id_osoba") ASC, "osoby"."id_osoba" ASC;

SELECT "osoby"."jmeno", "zarazeni"."do_o", "osoby"."prijmeni", "osoby"."narozeni", "osoby"."prijmeni", SUM("zarazeni"."cl_funkce"), COUNT("osoby"."id_osoba"), AVG("hl_zposlanec"."id_osoba")
FROM "zarazeni" LEFT JOIN "osoby" ON "zarazeni"."id_osoba" = "osoby"."id_osoba" JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" WHERE "osoby"."narozeni" = '21.11.1907' GROUP BY "osoby"."jmeno", "zarazeni"."do_o", "osoby"."prijmeni", "osoby"."narozeni", "osoby"."prijmeni" HAVING AVG("hl_zposlanec"."id_osoba") > 45 ORDER BY "osoby"."prijmeni" ASC, SUM("zarazeni"."cl_funkce") DESC;

SELECT "bod_schuze"."id_schuze", "schuze"."id_schuze", "bod_stav"."id_bod_stav", "bod_schuze"."druh_bodu", AVG("schuze"."id_organ"), AVG("bod_schuze"."bod")
FROM "bod_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" WHERE "bod_schuze"."pozn2" IS NULL AND "bod_schuze"."id_bod_stav" != 0 AND "bod_stav"."id_bod_stav" < 3 GROUP BY "bod_schuze"."id_schuze", "schuze"."id_schuze", "bod_stav"."id_bod_stav", "bod_schuze"."druh_bodu" ORDER BY "bod_stav"."id_bod_stav" DESC, "schuze"."id_schuze" DESC LIMIT 122;

