FROM "bod_schuze" JOIN "bod_stav" ON "bod_schuze"."id_bod_stav" = "bod_stav"."id_bod_stav" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_stav"."id_bod_stav" < 0 AND "bod_stav"."popis" != 'neprojednán' AND "bod_stav"."popis" != 'právě projednávaný' AND "schuze"."schuze" < 11 AND "bod_schuze"."uplny_kon" = '/sněmovní tisk 1004/' GROUP BY "schuze"."schuze", "bod_schuze"."id_bod_stav", "bod_stav"."id_bod_stav", "bod_stav"."popis" ORDER BY MAX("bod_schuze"."bod") ASC, "bod_stav"."popis" DESC LIMIT 787;

