FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" WHERE "bod_stav"."id_bod_stav" <= 2 AND "bod_schuze"."id_typ" = '54' AND "bod_stav"."id_bod_stav" <= 1 AND "bod_stav"."id_bod_stav" > 3 AND "bod_stav"."id_bod_stav" <= 4 GROUP BY "bod_schuze"."id_bod_stav", "bod_schuze"."id_tisk", "bod_stav"."popis", "bod_schuze"."uplny_kon", "bod_stav"."id_bod_stav" LIMIT 448;

