SELECT "hl_vazby"."typ", "hl_hlasovani"."druh_hlasovani", "hl_zposlanec"."mode", "hl_hlasovani"."nazev_kratky", AVG("hl_zposlanec"."mode"), MIN("hl_vazby"."typ")
FROM "hl_zposlanec" JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" WHERE "hl_vazby"."turn" != 220 AND "hl_zposlanec"."id_osoba" < 6217 AND "hl_hlasovani"."schuze" > 28 AND "hl_hlasovani"."pro" > 140 GROUP BY "hl_vazby"."typ", "hl_hlasovani"."druh_hlasovani", "hl_zposlanec"."mode", "hl_hlasovani"."nazev_kratky" HAVING MIN("hl_vazby"."typ") > 89 ORDER BY MIN("hl_vazby"."typ") ASC, "hl_hlasovani"."druh_hlasovani" ASC;

SELECT "organy"."nazev_organu_cz", "typ_organu"."typ_id_typ_org", "typ_organu"."id_typ_org", "organy"."do_organ", AVG("typ_organu"."id_typ_org"), MAX("typ_organu"."priorita"), COUNT("organy"."cl_organ_base")
