FROM "typ_funkce" JOIN "funkce" ON "typ_funkce"."id_typ_funkce" = "funkce"."id_typ_funkce" WHERE "typ_funkce"."id_typ_funkce" = 78 GROUP BY "typ_funkce"."typ_funkce_en", "typ_funkce"."id_typ_org", "funkce"."id_typ_funkce", "funkce"."priorita", "typ_funkce"."typ_funkce_obecny" LIMIT 519;

