SELECT "funkce"."priorita", "funkce"."id_typ_funkce", "funkce"."id_organ", "typ_funkce"."typ_funkce_obecny", "organy"."nazev_organu_cz", MIN("typ_funkce"."typ_funkce_obecny")
FROM "funkce" LEFT JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" WHERE "funkce"."id_funkce" <= 190 GROUP BY "funkce"."priorita", "funkce"."id_typ_funkce", "funkce"."id_organ", "typ_funkce"."typ_funkce_obecny", "organy"."nazev_organu_cz" HAVING MIN("typ_funkce"."typ_funkce_obecny") > 80 ORDER BY "typ_funkce"."typ_funkce_obecny" DESC, "organy"."nazev_organu_cz" ASC LIMIT 628;

SELECT "organy"."id_typ_organu", "organy"."priorita", "funkce"."nazev_funkce_cz", "typ_organu"."priorita", MIN("typ_organu"."priorita"), MIN("organy"."organ_id_organ")
