FROM "typ_organu" LEFT JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" WHERE "typ_funkce"."typ_funkce_en" = 'Secretary' OR "typ_funkce"."typ_funkce_cz" = '1. místopředseda' OR "typ_organu"."priorita" < 189 OR "typ_organu"."nazev_typ_org_cz" != 'Parlamentní shromáždění NATO' OR "typ_funkce"."typ_funkce_cz" = 'Ministr informatiky' GROUP BY "typ_funkce"."typ_funkce_obecny", "typ_organu"."nazev_typ_org_cz", "typ_funkce"."priorita" ORDER BY AVG("typ_organu"."id_typ_org") ASC, "typ_organu"."nazev_typ_org_cz" DESC LIMIT 873;

