FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."zdrzel" > 14 AND "hl_hlasovani"."nazev_dlouhy" = 'Inf. o voj. cvič. AČR se zahr. partnery leden - červen 2014' AND "hl_check"."mode" != -1 GROUP BY "hl_hlasovani"."nazev_kratky", "hl_check"."id_hlasovani", "hl_check"."id_h2", "hl_check"."id_h2" LIMIT 90;

SELECT "zmatecne"."id_hlasovani", "hl_zposlanec"."id_osoba", "hl_zposlanec"."mode", "hl_hlasovani"."datum", "zmatecne"."id_hlasovani", MIN("hl_check"."mode"), AVG("hl_hlasovani"."zdrzel"), SUM("zmatecne"."id_hlasovani")
FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_check"."id_hlasovani" >= 60146 AND "zmatecne"."id_hlasovani" <= 61287 GROUP BY "zmatecne"."id_hlasovani", "hl_zposlanec"."id_osoba", "hl_zposlanec"."mode", "hl_hlasovani"."datum", "zmatecne"."id_hlasovani" ORDER BY MIN("hl_check"."mode") ASC, "hl_zposlanec"."mode" ASC;

SELECT "hl_zposlanec"."mode", "zmatecne"."id_hlasovani", "hl_hlasovani"."bod", "hl_zposlanec"."id_hlasovani", COUNT("hl_zposlanec"."mode"), AVG("zmatecne"."id_hlasovani"), AVG("hl_hlasovani"."id_hlasovani")
FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_check"."id_hlasovani" <= 61396 GROUP BY "hl_zposlanec"."mode", "zmatecne"."id_hlasovani", "hl_hlasovani"."bod", "hl_zposlanec"."id_hlasovani" HAVING COUNT("hl_zposlanec"."mode") > 52 ORDER BY "hl_hlasovani"."bod" ASC, "hl_zposlanec"."mode" ASC LIMIT 248;

SELECT "poslanec"."id_kraj", "omluvy"."id_organ", COUNT("poslanec"."id_kraj"), AVG("omluvy"."id_organ")
FROM "omluvy" JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" LEFT JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "poslanec"."web" = 'http://www.jaroslav-klaska.cz/' AND "osoby"."id_osoba" = 4895 GROUP BY "poslanec"."id_kraj", "omluvy"."id_organ" HAVING COUNT("poslanec"."id_kraj") > 90;

SELECT "hl_check"."id_h3", "hl_check"."id_h2", "hl_check"."id_h3", MIN("hl_check"."mode")
FROM "hl_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_check"."turn" < 198 GROUP BY "hl_check"."id_h3", "hl_check"."id_h2", "hl_check"."id_h3" HAVING MIN("hl_check"."mode") > 67 ORDER BY "hl_check"."id_h3" DESC, "hl_check"."id_h3" DESC;

SELECT "organy"."od_organ", "organy"."od_organ", "organy"."do_organ", "typ_organu"."id_typ_org", AVG("typ_organu"."id_typ_org")
FROM "organy" LEFT JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" WHERE "organy"."id_typ_organu" >= 14 AND "typ_organu"."typ_id_typ_org" != '20' GROUP BY "organy"."od_organ", "organy"."od_organ", "organy"."do_organ", "typ_organu"."id_typ_org" ORDER BY "organy"."od_organ" DESC, "organy"."do_organ" DESC LIMIT 417;

SELECT "hl_vazby"."id_hlasovani", "hl_hlasovani"."prihlaseno", "hl_vazby"."id_hlasovani", COUNT("hl_vazby"."typ"), COUNT("hl_vazby"."turn"), AVG("hl_vazby"."turn")
FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_vazby"."id_hlasovani" < 58478 AND "hl_hlasovani"."id_organ" <= 5472 GROUP BY "hl_vazby"."id_hlasovani", "hl_hlasovani"."prihlaseno", "hl_vazby"."id_hlasovani" HAVING COUNT("hl_vazby"."typ") > 75 ORDER BY "hl_vazby"."id_hlasovani" DESC, "hl_hlasovani"."prihlaseno" DESC;

SELECT "schuze"."id_schuze", "schuze"."do_schuze", "schuze_stav"."stav", "schuze_stav"."text_dt", "schuze"."schuze", AVG("schuze"."id_schuze"), AVG("schuze_stav"."stav")
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."do_schuze" LIKE '%2012-11-09 14%' AND "schuze"."schuze" = 60 AND "schuze_stav"."id_schuze" < 358 AND "schuze"."id_organ" < 168 GROUP BY "schuze"."id_schuze", "schuze"."do_schuze", "schuze_stav"."stav", "schuze_stav"."text_dt", "schuze"."schuze" ORDER BY "schuze"."do_schuze" DESC, "schuze_stav"."text_dt" ASC LIMIT 687;

SELECT "schuze"."od_schuze", "omluvy"."od", COUNT("bod_schuze"."id_schuze"), SUM("bod_schuze"."id_bod_stav")
FROM "bod_schuze" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "omluvy"."id_organ" != 169 OR "organy"."nazev_organu_cz" LIKE '%Zahraniční výbor%' OR "bod_schuze"."id_typ" = '5' GROUP BY "schuze"."od_schuze", "omluvy"."od" HAVING SUM("bod_schuze"."id_bod_stav") > 31 ORDER BY "omluvy"."od" ASC, COUNT("bod_schuze"."id_schuze") DESC LIMIT 297;

SELECT "hl_hlasovani"."pro", "organy"."id_typ_organu", "omluvy"."od", "poslanec"."id_obdobi", COUNT("organy"."id_organ"), COUNT("poslanec"."id_osoba")
FROM "omluvy" JOIN "organy" ON "omluvy"."id_organ" = "organy"."id_organ" JOIN "poslanec" ON "omluvy"."id_poslanec" = "poslanec"."id_poslanec" LEFT JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" WHERE "hl_hlasovani"."nazev_dlouhy" != 'Návrhy PS na propůjčení nebo udělení státních vyznamenání' AND "omluvy"."do" IS NOT NULL GROUP BY "hl_hlasovani"."pro", "organy"."id_typ_organu", "omluvy"."od", "poslanec"."id_obdobi" ORDER BY "poslanec"."id_obdobi" ASC, COUNT("organy"."id_organ") ASC;

SELECT "bod_schuze"."id_sd", "bod_schuze"."poznamka", "schuze"."id_schuze", COUNT("schuze"."schuze"), MIN("bod_schuze"."id_bod_stav"), MIN("schuze"."id_schuze")
FROM "schuze" JOIN "bod_schuze" ON "schuze"."id_schuze" = "bod_schuze"."id_schuze" WHERE "schuze"."id_schuze" < 237 AND "bod_schuze"."pozvanka" = '1' GROUP BY "bod_schuze"."id_sd", "bod_schuze"."poznamka", "schuze"."id_schuze" ORDER BY MIN("bod_schuze"."id_bod_stav") DESC, COUNT("schuze"."schuze") DESC;

SELECT "organy"."od_organ", "organy"."zkratka", "organy"."od_organ", "schuze"."id_organ", MIN("organy"."cl_organ_base")
FROM "organy" LEFT JOIN "schuze" ON "organy"."id_organ" = "schuze"."id_organ" WHERE "organy"."organ_id_organ" = -1 AND "organy"."nazev_organu_en" != 'Bolivarian Republic of Venezuela' GROUP BY "organy"."od_organ", "organy"."zkratka", "organy"."od_organ", "schuze"."id_organ";

SELECT "hl_hlasovani"."cislo", "typ_organu"."nazev_typ_org_cz", "typ_funkce"."priorita", "typ_organu"."typ_org_obecny", "typ_funkce"."typ_funkce_cz", AVG("typ_organu"."priorita")
FROM "organy" JOIN "hl_hlasovani" ON "organy"."id_organ" = "hl_hlasovani"."id_organ" JOIN "typ_organu" ON "organy"."id_typ_organu" = "typ_organu"."id_typ_org" JOIN "typ_funkce" ON "typ_organu"."id_typ_org" = "typ_funkce"."id_typ_org" WHERE "typ_organu"."nazev_typ_org_cz" = 'Meziparlamentní skupina v rámci MPU' AND "typ_funkce"."priorita" = 27 AND "typ_organu"."nazev_typ_org_en" IS NULL GROUP BY "hl_hlasovani"."cislo", "typ_organu"."nazev_typ_org_cz", "typ_funkce"."priorita", "typ_organu"."typ_org_obecny", "typ_funkce"."typ_funkce_cz" ORDER BY AVG("typ_organu"."priorita") ASC, "typ_organu"."nazev_typ_org_cz" ASC LIMIT 84;

SELECT "hl_poslanec"."id_poslanec", "hl_poslanec"."id_hlasovani", "hl_poslanec"."id_hlasovani", "poslanec"."id_osoba", MIN("hl_poslanec"."id_poslanec"), SUM("poslanec"."id_kraj")
FROM "hl_poslanec" JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."web" IS NULL AND "poslanec"."psp_telefon" = '\' AND "hl_poslanec"."id_hlasovani" != 60144 GROUP BY "hl_poslanec"."id_poslanec", "hl_poslanec"."id_hlasovani", "hl_poslanec"."id_hlasovani", "poslanec"."id_osoba" ORDER BY MIN("hl_poslanec"."id_poslanec") DESC, "poslanec"."id_osoba" DESC LIMIT 216;

SELECT "hl_hlasovani"."cislo", "hl_zposlanec"."id_hlasovani", SUM("hl_hlasovani"."kvorum"), MAX("hl_hlasovani"."cislo")
FROM "hl_hlasovani" LEFT JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" WHERE "hl_zposlanec"."mode" < 6 GROUP BY "hl_hlasovani"."cislo", "hl_zposlanec"."id_hlasovani" LIMIT 397;

SELECT "organy"."organ_id_organ", "hl_check"."turn", "organy"."nazev_organu_cz", "hl_check"."id_h3", COUNT("hl_hlasovani"."bod")
FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "organy" ON "hl_hlasovani"."id_organ" = "organy"."id_organ" WHERE "hl_check"."turn" = 48 AND "organy"."zkratka" != 'SKRRP' GROUP BY "organy"."organ_id_organ", "hl_check"."turn", "organy"."nazev_organu_cz", "hl_check"."id_h3" HAVING COUNT("hl_hlasovani"."bod") > 74 LIMIT 589;

SELECT "schuze_stav"."text_dt", "bod_schuze"."pozvanka", "bod_schuze"."druh_bodu", "schuze_stav"."tm_line", "schuze_stav"."typ", MIN("schuze_stav"."id_schuze"), COUNT("schuze_stav"."stav"), MIN("schuze_stav"."id_schuze")
FROM "bod_stav" LEFT JOIN "bod_schuze" ON "bod_stav"."id_bod_stav" = "bod_schuze"."id_bod_stav" LEFT JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" WHERE "schuze_stav"."text_dt" IS NOT NULL AND "schuze"."od_schuze" LIKE '%2002-08-23 10%' AND "schuze"."id_organ" != 165 GROUP BY "schuze_stav"."text_dt", "bod_schuze"."pozvanka", "bod_schuze"."druh_bodu", "schuze_stav"."tm_line", "schuze_stav"."typ" LIMIT 652;

SELECT "hl_check"."id_h3", "hl_hlasovani"."pro", SUM("zmatecne"."id_hlasovani"), AVG("hl_hlasovani"."cislo")
FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "hl_zposlanec"."id_hlasovani" >= 60817 AND "hl_hlasovani"."druh_hlasovani" = 'N' AND "hl_hlasovani"."vysledek" != 'R' AND "hl_check"."mode" = 1 GROUP BY "hl_check"."id_h3", "hl_hlasovani"."pro" ORDER BY SUM("zmatecne"."id_hlasovani") ASC, "hl_hlasovani"."pro" DESC;

SELECT "hl_check"."turn", "hl_zposlanec"."id_hlasovani", "hl_check"."id_h2", "hl_vazby"."turn", MIN("hl_zposlanec"."mode")
FROM "hl_vazby" JOIN "hl_hlasovani" ON "hl_vazby"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_zposlanec" ON "hl_hlasovani"."id_hlasovani" = "hl_zposlanec"."id_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_vazby"."typ" >= -6 OR "hl_check"."id_h2" IS NOT NULL GROUP BY "hl_check"."turn", "hl_zposlanec"."id_hlasovani", "hl_check"."id_h2", "hl_vazby"."turn" LIMIT 171;

SELECT "hl_hlasovani"."zdrzel", "zmatecne"."id_hlasovani", "hl_hlasovani"."zdrzel", "hl_hlasovani"."zdrzel", MAX("hl_hlasovani"."schuze")
FROM "zmatecne" JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_hlasovani"."prihlaseno" = 166 AND "hl_hlasovani"."nazev_dlouhy" = 'Inf. o voj. cvič. AČR se zahr. partnery leden - červen 2014' AND "zmatecne"."id_hlasovani" < 61589 AND "hl_hlasovani"."cas" != 'default' GROUP BY "hl_hlasovani"."zdrzel", "zmatecne"."id_hlasovani", "hl_hlasovani"."zdrzel", "hl_hlasovani"."zdrzel" ORDER BY "hl_hlasovani"."zdrzel" ASC, "hl_hlasovani"."zdrzel" DESC;

SELECT "zarazeni"."id_of", "osoby"."umrti", "zarazeni"."do_o", "poslanec"."id_obdobi", "hl_zposlanec"."id_osoba", MIN("osoby"."id_osoba"), MIN("zarazeni"."id_osoba")
FROM "poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" LEFT JOIN "hl_zposlanec" ON "osoby"."id_osoba" = "hl_zposlanec"."id_osoba" WHERE "poslanec"."id_osoba" >= 1215 AND "hl_zposlanec"."mode" <= 3 AND "zarazeni"."do_o" IS NOT NULL AND "osoby"."za" IS NULL AND "poslanec"."fax" = '\' GROUP BY "zarazeni"."id_of", "osoby"."umrti", "zarazeni"."do_o", "poslanec"."id_obdobi", "hl_zposlanec"."id_osoba" HAVING MIN("zarazeni"."id_osoba") > 74 ORDER BY "poslanec"."id_obdobi" ASC, "osoby"."umrti" DESC;

SELECT "schuze_stav"."tm_line", "schuze_stav"."typ", MIN("schuze_stav"."stav")
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "schuze_stav" ON "schuze"."id_schuze" = "schuze_stav"."id_schuze" JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "schuze_stav"."text_st" = 'návrh na vyslovení nedůvěry vládě ČR' OR "schuze_stav"."stav" = 1 OR "schuze_stav"."tm_line" != 'Přerušeno do středy 25. listopadu do 9 hodin.' GROUP BY "schuze_stav"."tm_line", "schuze_stav"."typ" ORDER BY MIN("schuze_stav"."stav") ASC, "schuze_stav"."typ" DESC LIMIT 766;

SELECT "organy"."nazev_organu_cz", "typ_funkce"."typ_funkce_obecny", "funkce"."id_funkce", "omluvy"."id_poslanec", AVG("funkce"."id_organ"), AVG("omluvy"."id_poslanec"), AVG("organy"."id_organ")
FROM "funkce" LEFT JOIN "typ_funkce" ON "funkce"."id_typ_funkce" = "typ_funkce"."id_typ_funkce" JOIN "organy" ON "funkce"."id_organ" = "organy"."id_organ" LEFT JOIN "omluvy" ON "organy"."id_organ" = "omluvy"."id_organ" WHERE "funkce"."nazev_funkce_cz" != 'Tajemník-ověř. výboru ORGV' AND "funkce"."nazev_funkce_cz" LIKE '%Předseda%' GROUP BY "organy"."nazev_organu_cz", "typ_funkce"."typ_funkce_obecny", "funkce"."id_funkce", "omluvy"."id_poslanec" ORDER BY "typ_funkce"."typ_funkce_obecny" ASC, "funkce"."id_funkce" ASC;

SELECT "hl_poslanec"."vysledek", "poslanec"."id_obdobi", SUM("hl_poslanec"."id_poslanec"), COUNT("poslanec"."id_poslanec")
FROM "hl_poslanec" JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" WHERE "poslanec"."psp_telefon" IS NULL OR "poslanec"."psc" = '79201' OR "poslanec"."id_kraj" = 159 GROUP BY "hl_poslanec"."vysledek", "poslanec"."id_obdobi";

